}

/* ----------------------------------------------------------------------------
   16. COMMAND PALETTE : Ctrl/Cmd+K (surface flottante)
   -------------------------------------------------------------------------- */
.pv2-palette-overlay {
  position: fixed;
  inset: 0;
  z-index: 450;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 12vh 16px 16px;
  background: var(--scrim);
}

.pv2-palette {
  width: min(620px, 100%);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--raised);
  box-shadow: var(--shadow-overlay);
  overflow: hidden;
  animation: pl-enter var(--dur-slow) var(--ease) both;
}

.pv2-palette-input {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  transition: border-color var(--dur-fast) var(--ease);
}

.pv2-palette-input:focus-within { border-bottom-color: var(--accent); }

.pv2-palette-input svg { width: 16px; height: 16px; stroke: var(--faint); flex: none; }

.pv2-palette-input input {
  flex: 1;
  height: auto;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--text);
  font-family: var(--font-ui);
  font-size: 15px;
}

.pv2-palette-input input:focus { outline: none; box-shadow: none; }

.pv2-palette-list { max-height: 340px; overflow: auto; padding: 6px; }

.pv2-palette-section {
  padding: 8px 11px 4px;
  color: var(--faint);
  font-size: 11px;
  font-weight: 500;
}

.pv2-palette-item {
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  min-height: 40px;
  padding: 6px 10px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease);
}

.pv2-palette-item:hover { background: var(--subtle); }
.pv2-palette-item.active { background: var(--accent-soft); color: var(--text); }

.pv2-palette-ico {
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--muted);
  font-size: 12px;
  flex: none;
}

.pv2-palette-item.active .pv2-palette-ico { border-color: var(--accent); color: var(--accent-strong); }
.pv2-palette-item small { margin-left: auto; color: var(--faint); font-size: 11px; }

.pv2-palette-foot {
  display: flex;
  gap: var(--space-4);
  padding: 9px 16px;
  border-top: 1px solid var(--line);
  color: var(--faint);
  font-size: 11px;
}

.pv2-palette-foot kbd { margin-right: 4px; }

/* ----------------------------------------------------------------------------
   17. OVERLAYS : fiche POS, modale édition, réservation rapide, toast,
   aperçu email. Seules surfaces à porter --shadow-overlay.
   -------------------------------------------------------------------------- */
.pos-overlay:not(.hidden) {
  position: fixed;
  inset: 0;
  z-index: 420;
  display: flex;
  justify-content: flex-end;
  background: var(--scrim);
}

.pos-overlay.centered:not(.hidden) { justify-content: center; align-items: center; padding: var(--space-6); }

.pos-panel {
  width: 460px;
  max-width: 100%;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  background: var(--raised);
  border-left: 1px solid var(--line);
  box-shadow: var(--shadow-overlay);
}

.pos-head { padding: var(--space-5); border-bottom: 1px solid var(--line); }
.pos-head-top { display: flex; justify-content: space-between; align-items: flex-start; gap: var(--space-3); margin-bottom: var(--space-4); }
.pos-head h3 { font-size: 20px; }

.ticket-id {
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-size: 11px;
  color: var(--faint);
  font-weight: 500;
}

.close-btn {
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-full);
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
  flex: none;
  transition: background-color var(--dur) var(--ease), color var(--dur) var(--ease);
}

.close-btn:hover { background: var(--subtle); color: var(--text); }

.tabs, .modal-tabs {
  display: flex;
  gap: 2px;
  padding: 3px;
  background: var(--subtle);
  border-radius: var(--radius-md);
}

.tab {
  flex: 1;
  min-height: 30px;
  padding: 0 12px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), color var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
}

.tab:hover { color: var(--text); }
.tab.active { background: var(--surface); color: var(--text); box-shadow: var(--shadow-sm), 0 0 0 1px var(--line); }

.pos-body { flex: 1; overflow-y: auto; padding: var(--space-5); }

.info-block {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
  margin-bottom: var(--space-3);
}

.info-block.soft { background: var(--page); }
.info-block.compact { padding: var(--space-3); }

.info-label { font-size: 12px; color: var(--muted); font-weight: 500; margin-bottom: 10px; }
.info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-4); }
/* `--faint` mesure 3,23:1 sur `--surface` en clair : sous le seuil AA de 4,5:1.
   L'intitulé d'un champ est ce qui dit CE QU'ON LIT ; il ne peut pas être le
   texte le moins lisible de l'écran. Même correction que l'effectif des cartes
   du planning le 2026-08-13 (journal 141), au même endroit du raisonnement. */
.info-row .lbl { font-size: 11px; color: var(--muted); font-weight: 500; margin-bottom: 3px; }
.info-row .val { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 15px; font-weight: 600; }
.info-row .val small { font-size: 11px; color: var(--muted); font-weight: 400; }

/* HIÉRARCHIE DE LECTURE DANS LA FICHE. Huit blocs empilés portaient tous un
   titre au même poids (12px/500 gris) : rien ne disait par quoi commencer.
   Le titre de section passe en `--text` et en 600, les intitulés de champ
   restent en 11px `--muted` : deux niveaux qui se distinguent d'un coup d'œil,
   sans ajouter ni trait ni couleur. */
.edit-modal-body .info-label { color: var(--text); font-weight: 600; letter-spacing: -0.01em; }
.edit-modal-body .info-block { margin-bottom: var(--space-4); }
.edit-modal-body .info-block:last-child { margin-bottom: 0; }
/* Il y avait ici une règle qui teintait le PREMIER bloc de la fiche pour en
   faire « le point d'entrée du regard ». Ce bloc recopiait mot pour mot le
   sous-titre de l'en-tête : on mettait donc en valeur une redite. Le point
   d'entrée est maintenant le bloc d'action (`.pos-act`), et c'est la seule
   surface soulevée de la fiche. */

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 10px;
  border-radius: var(--radius-full);
  background: var(--subtle);
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
}

.status-pill .dot { width: 6px; height: 6px; background: currentColor; }
.status-pill.conf { background: var(--info-soft); color: var(--accent-strong); }
.status-pill.arr { background: var(--warning-soft); color: var(--warning); }
.status-pill.paid { background: var(--success-soft); color: var(--success); }

.delay-control-copy { color: var(--muted); font-size: 12px; line-height: 1.5; margin-bottom: 10px; }
.delay-control-actions { display: flex; gap: 6px; flex-wrap: wrap; }

/* Ces contrôles étaient les seuls de la console en pilule (`--radius-full`)
   pendant que tout le reste est en `--radius-sm` : une forme unique qui ne
   voulait rien dire de particulier. Ils rentrent dans le système. Le monospace
   reste sur les VALEURS (« +5 min »), qui sont des données, et sort du bouton
   « Analyser ce retard », qui est une phrase (DESIGN.md §4). */
.delay-chip {
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), border-color var(--dur) var(--ease);
}

.delay-chip:hover { background: var(--warning-soft); border-color: var(--warning); color: var(--warning); }
.delay-chip-now { border-color: var(--warning); color: var(--warning); }
.delay-chip-run { font-family: var(--font-ui); font-variant-numeric: normal; }

.delay-custom-row { display: flex; gap: 6px; align-items: center; margin-top: 8px; }
.delay-custom-row input {
  width: 96px;
  height: 32px;
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-size: 12px;
}

/* Modale retard : preview d'impact + étape notification clients */
.delay-overlay {
  position: fixed;
  inset: 0;
  z-index: 440;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  background: var(--scrim);
}

.delay-overlay.hidden { display: none; }

.delay-modal {
  width: min(680px, calc(100vw - 24px));
  max-height: calc(100dvh - 28px);
  display: flex;
  flex-direction: column;
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-overlay);
  overflow: hidden;
}

.delay-modal-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-4);
  padding: var(--space-5) var(--space-5) var(--space-4);
  border-bottom: 1px solid var(--line);
}

.delay-modal-head h3 { font-size: 16px; }
.delay-modal-head p { color: var(--muted); font-size: 12px; margin-top: 4px; }
.delay-modal-body { flex: 1; min-height: 0; overflow: auto; padding: var(--space-5); display: grid; gap: var(--space-3); align-content: start; }
.delay-modal-foot {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  padding: var(--space-4) var(--space-5);
  border-top: 1px solid var(--line);
}

.delay-btn {
  min-height: 36px;
  padding: 0 16px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), border-color var(--dur) var(--ease), opacity var(--dur) var(--ease);
}

.delay-btn:disabled { opacity: 0.55; cursor: not-allowed; }
.delay-btn-primary { background: var(--accent); border-color: var(--accent); color: var(--accent-contrast); }
.delay-btn-primary:not(:disabled):hover { opacity: 0.9; }

.delay-loading { color: var(--muted); font-size: 13px; padding: var(--space-4) 0; text-align: center; }

.delay-context {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  flex-wrap: wrap;
  font-size: 13px;
  color: var(--text);
  padding: var(--space-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  font-variant-numeric: tabular-nums;
}

.delay-section-title {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: var(--space-2);
}

.delay-strategy-list { display: grid; gap: var(--space-2); }

.delay-strategy {
  display: flex;
  gap: var(--space-3);
  align-items: flex-start;
  padding: var(--space-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  cursor: pointer;
  transition: border-color var(--dur) var(--ease), background-color var(--dur) var(--ease);
}

.delay-strategy input { margin-top: 3px; accent-color: var(--accent); }
.delay-strategy.is-selected { border-color: var(--accent); }
.delay-strategy.is-disabled { opacity: 0.55; cursor: not-allowed; }
.delay-strategy-body { display: grid; gap: 3px; min-width: 0; }
.delay-strategy-head { display: flex; align-items: center; gap: 8px; font-size: 13px; flex-wrap: wrap; }
.delay-strategy-reco {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--success);
  border: 1px solid var(--success);
  border-radius: var(--radius-full);
  padding: 1px 8px;
}
.delay-strategy-desc { color: var(--muted); font-size: 12px; line-height: 1.45; }

.delay-plan-list { display: grid; gap: var(--space-2); }
.delay-plan-empty { color: var(--muted); font-size: 12px; }

.delay-plan-row {
  display: grid;
  gap: 3px;
  padding: var(--space-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.delay-plan-row.is-delayed { border-color: var(--warning); }
.delay-plan-name { font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.delay-plan-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--warning);
  border: 1px solid var(--warning);
  border-radius: var(--radius-full);
  padding: 1px 8px;
}
.delay-plan-summary { color: var(--muted); font-size: 12px; line-height: 1.45; font-variant-numeric: tabular-nums; }

.delay-warning {
  padding: var(--space-3);
  border: 1px solid var(--warning);
  border-radius: var(--radius-md);
  background: var(--warning-soft);
  color: var(--warning);
  font-size: 12px;
  line-height: 1.45;
}

.delay-confirm-note { color: var(--muted); font-size: 11px; line-height: 1.5; }

.delay-applied-banner {
  padding: var(--space-3);
  border: 1px solid var(--success);
  border-radius: var(--radius-md);
  background: var(--success-soft);
  color: var(--success);
  font-size: 12px;
  font-weight: 600;
}

.delay-notify-intro { color: var(--muted); font-size: 12px; line-height: 1.5; }
.delay-notify-list { display: grid; gap: var(--space-2); }

.delay-notify-body { display: grid; gap: 2px; min-width: 0; }
.delay-notify-name { font-size: 13px; font-weight: 600; }
.delay-notify-summary { color: var(--muted); font-size: 12px; line-height: 1.4; }
.delay-notify-email { color: var(--muted); font-size: 11px; font-family: var(--font-data); }

/* Étape notification retard mise en évidence + message éditable par client */
.delay-notify-prominent {
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--accent);
  border-radius: var(--radius-md);
  background: var(--accent-soft);
  display: grid;
  gap: 6px;
}
.delay-notify-step {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--accent-strong, var(--accent));
}
.delay-notify-card {
  display: grid;
  gap: var(--space-2);
  padding: var(--space-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  transition: border-color var(--dur-fast) var(--ease), opacity var(--dur-fast) var(--ease);
}
.delay-notify-card.is-on { border-color: var(--accent); }
.delay-notify-card.is-off { opacity: 0.62; }
.delay-notify-head { display: flex; gap: var(--space-3); align-items: flex-start; cursor: pointer; }
.delay-notify-head input { margin-top: 3px; accent-color: var(--accent); }
.delay-notify-textarea {
  width: 100%;
  resize: vertical;
  padding: var(--space-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-2, var(--surface));
  color: var(--text);
  font: inherit;
  font-size: 13px;
  line-height: 1.5;
}
.delay-notify-textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.delay-notify-textarea:disabled { opacity: 0.5; cursor: not-allowed; }

/* Indicateur de retard sur les cartes planning (bowling + laser) */
/* LE RETARD SE SIGNALE, IL NE CRIE PAS (2026-08-27). Movsar : « rends plus petit
   et quali le truc de retard ». Le cerne plein et la bordure pleine en faisaient
   l element le plus bruyant d une carte de planning, devant le nom du client.
   Fond et bordure s adoucissent, la pastille maigrit ; la couleur d alerte reste
   sur le texte et l icone, qui suffisent a la faire remarquer. */
.delay-indicator {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 0 4px 0 3px;
  border: 1px solid color-mix(in srgb, var(--warning) 40%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--warning) 12%, transparent);
  color: var(--warning);
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
}
.delay-indicator:hover { filter: brightness(0.96); }
.delay-indicator .delay-indicator-label { font-variant-numeric: tabular-nums; }
.booking .delay-indicator { margin-left: auto; flex: none; }
.booking.is-delayed { border-left-color: var(--warning); box-shadow: inset 0 0 0 1px var(--warning-soft); }
.laser-group-card.is-delayed { box-shadow: inset 0 0 0 1px var(--warning); }
.laser-group-card .delay-indicator { margin-left: auto; }

/* Bouton d'ouverture du centre de communication (fiche résa) */
/* Trois ecarts au systeme sur un seul bouton : une hauteur de 35 px la ou la
   console n'en connait que 32 et 36, un rayon `--radius-md` la ou tous les
   autres controles sont en `--radius-sm`, et un fond plein d'accent qui en
   faisait l'element le plus bruyant de la fiche alors que c'est une action
   SECONDAIRE (l'action de la fiche, c'est l'etat du dossier). Il redevient un
   bouton de la meme famille que les autres, et ne prend l'accent qu'au survol. */
.comm-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--accent-strong);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease);
}
.comm-open-btn:hover { background: var(--accent-soft); border-color: var(--accent); }

/* Centre de communication client (modale) */
.comm-modal { max-width: 560px; }
.comm-channels { display: flex; gap: var(--space-2); }
.comm-channel-btn {
  flex: 1;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.comm-channel-btn.is-active { border-color: var(--accent); background: var(--accent-soft); color: var(--accent-strong, var(--accent)); }
.comm-channel-btn.is-disabled { opacity: 0.55; cursor: not-allowed; }
.comm-channel-tag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
}
.comm-warning {
  padding: var(--space-3);
  border: 1px solid var(--warning);
  border-radius: var(--radius-md);
  background: var(--warning-soft);
  color: var(--warning);
  font-size: 12px;
  line-height: 1.45;
}
.comm-field { display: grid; gap: 5px; }
.comm-label { font-size: 11px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: var(--muted); }
.comm-select, .comm-input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-size: 13px;
}
.comm-select:focus, .comm-input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.comm-template-desc { color: var(--muted); font-size: 12px; line-height: 1.4; }
.comm-recipient { font-size: 12px; color: var(--muted); font-family: var(--font-data); }
.comm-recipient.is-missing { color: var(--warning); }
.comm-textarea {
  width: 100%;
  resize: vertical;
  padding: var(--space-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-2, var(--surface));
  color: var(--text);
  font: inherit;
  font-size: 13px;
  line-height: 1.5;
}
.comm-textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.comm-char-counter { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; text-align: right; }
.comm-preview {
  padding: var(--space-3);
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-md);
  background: var(--surface);
  display: grid;
  gap: 5px;
}
.comm-preview-label { font-size: 10px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); }
.comm-preview-body { font-size: 12px; line-height: 1.55; white-space: pre-wrap; color: var(--text); }
.comm-history { display: grid; gap: var(--space-2); }
.comm-history-title { font-size: 11px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--muted); }
.comm-history-empty { color: var(--muted); font-size: 12px; }
.comm-history-row {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
}
.comm-history-chan {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-strong, var(--accent));
}
.comm-history-chan.sms { background: var(--info-soft, var(--accent-soft)); color: var(--info, var(--accent)); }
.comm-history-main { display: grid; gap: 1px; min-width: 0; flex: 1; }
.comm-history-subject { font-size: 12px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.comm-history-meta { font-size: 10px; color: var(--muted); font-family: var(--font-data); }
.comm-history-status { font-size: 11px; font-weight: 600; }
.comm-history-status.ok { color: var(--success); }
.comm-history-status.err { color: var(--danger); }
.comm-history-status.wait { color: var(--muted); }

/* LA FENETRE « MESSAGE AU CLIENT » (2026-10-01, Movsar : « la ca fait
   interface des annees 2006 »). A gauche on ecrit, a droite le vrai mail tel
   que le client le recoit. Sur telephone, deux onglets. */
.comm-modal.cm { max-width: none; width: min(1120px, calc(100vw - 24px)); height: min(860px, calc(100dvh - 28px)); }
.cm-head { display: flex; align-items: center; gap: var(--space-4); padding: var(--space-4) var(--space-5); border-bottom: 1px solid var(--line); }
.cm-head-txt { min-width: 0; flex: 1; }
.cm-kicker { display: block; font-size: 11px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); }
.cm-head h3 { font-size: 19px; font-weight: 650; line-height: 1.25; margin-top: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cm-head p { margin-top: 2px; font-size: 12.5px; color: var(--muted); }
.cm-chans { display: inline-flex; gap: 2px; padding: 3px; border: 1px solid var(--line); border-radius: var(--radius-full); background: var(--subtle); }
.cm-chan-btn { display: inline-flex; align-items: center; gap: 6px; min-height: 32px; padding: 0 14px; border: 0; border-radius: var(--radius-full); background: transparent; color: var(--muted); font: 600 13px/1 var(--font-ui); cursor: pointer; }
.cm-chan-btn.is-active { background: var(--surface); color: var(--text); box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12); }
.cm-chan-btn.is-disabled { opacity: 0.6; cursor: not-allowed; }
.cm-chan-btn .comm-channel-tag { margin-left: 2px; white-space: nowrap; }
.cm-tabs { display: none; }
.cm-body { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.cm-compose { min-height: 0; overflow: auto; padding: var(--space-5); display: flex; flex-direction: column; gap: var(--space-4); }
/* La colonne defile : rien ne s ecrase pour tenir (la lettre devenait un trait sur telephone). */
.cm-compose > * { flex-shrink: 0; }
.cm-label { font-size: 11px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); }
.cm-block { display: flex; flex-direction: column; gap: var(--space-2); }
.cm-tpls { display: flex; flex-direction: column; gap: 10px; }
.cm-tpl-group { display: grid; grid-template-columns: 92px minmax(0, 1fr); align-items: start; gap: var(--space-2); }
.cm-tpl-cat { padding-top: 7px; font-size: 12px; color: var(--muted); }
.cm-tpl-row { display: flex; flex-wrap: wrap; gap: 6px; }
.cm-tpl { min-height: 32px; padding: 0 12px; border: 1px solid var(--line-strong); border-radius: var(--radius-full); background: var(--surface); color: var(--text); font: 500 13px/1 var(--font-ui); cursor: pointer; transition: background-color var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease); }
.cm-tpl:hover { border-color: var(--accent); }
.cm-tpl.is-on { background: var(--accent-soft); border-color: var(--accent); color: var(--accent-strong, var(--accent)); font-weight: 600; }
.cm-tpl:disabled { opacity: 0.45; cursor: not-allowed; }
.cm-tpl:focus-visible, .cm-chan-btn:focus-visible, .cm-tab:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.cm-tpl-desc { font-size: 12.5px; color: var(--muted); }
.cm-letter { display: flex; flex-direction: column; border: 1px solid var(--line-strong); border-radius: var(--radius-lg); background: var(--surface); overflow: hidden; }
.cm-letter:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.cm-line { display: flex; align-items: center; gap: var(--space-3); min-height: 46px; padding: 0 var(--space-4); border-bottom: 1px solid var(--line); }
.cm-line-k { flex: none; width: 44px; font-size: 13px; color: var(--muted); }
.cm-line-v { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 8px; min-width: 0; font-size: 14px; }
.cm-line-v .comm-recipient { font-size: 12.5px; }
.cm-to.is-missing .cm-line-v { color: var(--warning); }
.cm-letter .cm-subject { flex: 1; min-width: 0; border: 0; background: transparent; padding: 0; font-size: 14px; font-weight: 600; box-shadow: none; }
.cm-letter .cm-subject:focus { box-shadow: none; }
.cm-letter .cm-text { border: 0; border-radius: 0; background: transparent; padding: var(--space-4); min-height: 240px; font-size: 14.5px; line-height: 1.6; resize: vertical; box-shadow: none; }
.cm-letter .cm-text:focus { box-shadow: none; }
.cm-letter .comm-char-counter { padding: 0 var(--space-4) var(--space-3); }
.cm-sent { display: flex; align-items: flex-start; gap: var(--space-2); padding: 10px 14px; border-radius: var(--radius-md); background: var(--success-soft); color: var(--success); font-size: 13.5px; }
.cm-sent svg { flex: none; margin-top: 2px; }
.cm-sent span { color: var(--text); }
.cm-sent b { color: var(--success); }
.cm-history { border-top: 1px solid var(--line); padding-top: var(--space-3); }
.cm-history summary { display: flex; align-items: center; gap: var(--space-2); cursor: pointer; list-style: none; }
.cm-history summary::-webkit-details-marker { display: none; }
.cm-history summary::after { content: ""; width: 7px; height: 7px; margin-left: auto; border-right: 1.5px solid var(--muted); border-bottom: 1.5px solid var(--muted); transform: rotate(45deg); transition: transform var(--dur-fast) var(--ease); }
.cm-history[open] summary::after { transform: rotate(-135deg); }
.cm-count { min-width: 20px; padding: 1px 7px; border-radius: var(--radius-full); background: var(--subtle); font-size: 11.5px; font-weight: 600; color: var(--muted); text-align: center; }
.cm-history-list { display: grid; gap: var(--space-2); margin-top: var(--space-3); }
.cm-preview { min-height: 0; display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-5); background: var(--subtle); border-left: 1px solid var(--line); }
.cm-preview-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); }
.cm-preview-state { font-size: 12px; color: var(--muted); }
.cm-preview-state[data-etat="ok"] { color: var(--success); }
.cm-preview-state[data-etat="ko"] { color: var(--warning); }
.cm-inbox { flex: 1; min-height: 0; display: flex; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius-lg); background: #ffffff; color: #1a1a1a; overflow: hidden; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12); }
.cm-inbox-meta { display: flex; align-items: center; gap: 10px; padding: 12px 16px 6px; }
.cm-avatar { width: 32px; height: 32px; flex: none; display: grid; place-items: center; border-radius: 50%; background: #1f1f1f; color: #ffffff; font-size: 14px; font-weight: 700; }
.cm-inbox-from { display: flex; flex-direction: column; min-width: 0; font-size: 13px; line-height: 1.3; }
.cm-inbox-from b { color: #111111; font-weight: 600; }
.cm-inbox-from small { color: #6b6b6b; font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cm-inbox-subject { padding: 4px 16px 12px; border-bottom: 1px solid #ececec; font-size: 15px; font-weight: 650; color: #111111; }
.cm-frame { flex: 1; width: 100%; min-height: 0; border: 0; background: #ffffff; transition: opacity var(--dur-fast) var(--ease); }
.cm-frame.is-vide { opacity: 0.35; }
.cm-phone { align-self: center; width: min(320px, 100%); flex: 1; min-height: 0; padding: 24px 16px; border: 1px solid var(--line); border-radius: 28px; background: var(--surface); }
.cm-bubble { max-width: 85%; padding: 10px 14px; border-radius: 16px 16px 16px 4px; background: var(--subtle); font-size: 14px; line-height: 1.45; white-space: pre-wrap; }
.cm-foot { display: flex; justify-content: flex-end; align-items: center; gap: var(--space-2); padding: var(--space-3) var(--space-5); border-top: 1px solid var(--line); }
.cm-send { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 40px; padding: 0 18px; font-weight: 600; white-space: nowrap; }
.cm-loading { flex: 1; display: flex; align-items: center; justify-content: center; gap: 10px; min-height: 240px; color: var(--muted); font-size: 14px; }
.cm-spin { width: 16px; height: 16px; border: 2px solid var(--line-strong); border-top-color: var(--accent); border-radius: 50%; animation: cm-tourne 0.8s linear infinite; }
@keyframes cm-tourne { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .cm-spin { animation: none; } }
@media (max-width: 860px) {
  .comm-modal.cm { width: calc(100vw - 16px); height: calc(100dvh - 16px); }
  .cm-head { flex-wrap: wrap; padding: var(--space-3) var(--space-4); }
  .cm-head-txt { order: 1; flex-basis: calc(100% - 48px); }
  .cm-head .close-btn { order: 2; }
  .cm-chans { order: 3; }
  .cm-tabs { display: flex; gap: 4px; padding: var(--space-2) var(--space-4) 0; border-bottom: 1px solid var(--line); }
  .cm-tab { flex: 1; min-height: 40px; border: 0; border-bottom: 2px solid transparent; background: transparent; color: var(--muted); font: 600 14px/1 var(--font-ui); cursor: pointer; }
  .cm-tab.is-on { color: var(--text); border-bottom-color: var(--accent); }
  .cm-body { grid-template-columns: minmax(0, 1fr); }
  .cm-body[data-vue="ecrire"] .cm-preview, .cm-body[data-vue="apercu"] .cm-compose { display: none; }
  .cm-compose, .cm-preview { padding: var(--space-4); }
  .cm-preview { border-left: 0; }
  /* Sur telephone, les modeles en une bande qui defile : la lettre reste a portee. */
  .cm-tpls { flex-direction: row; gap: 6px; overflow-x: auto; margin: 0 calc(-1 * var(--space-4)); padding: 2px var(--space-4) 6px; scrollbar-width: none; }
  .cm-tpls::-webkit-scrollbar { display: none; }
  .cm-tpl-group, .cm-tpl-row { display: contents; }
  .cm-tpl-cat { display: none; }
  .cm-tpl { min-height: 38px; flex: none; white-space: nowrap; }
  .cm-foot { padding: var(--space-3) var(--space-4); }
  .cm-foot .delay-btn { flex: 1; min-height: 44px; justify-content: center; }
}

/* Caisse / reçu */
.receipt {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  margin-bottom: var(--space-4);
  overflow: hidden;
}

.receipt-head { text-align: center; padding-bottom: var(--space-3); border-bottom: 1px dashed var(--line-strong); margin-bottom: var(--space-3); }
.receipt-head .title { font-size: 15px; font-weight: 600; letter-spacing: 0.04em; }
.receipt-line { display: flex; justify-content: space-between; gap: 10px; padding: 6px 0; font-size: 13px; font-variant-numeric: tabular-nums; }

.receipt-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-top: var(--space-3);
  padding-top: var(--space-3);
  border-top: 1px dashed var(--line-strong);
}

.receipt-total .lbl { font-size: 12px; font-weight: 500; color: var(--muted); }
.receipt-total .amount { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 22px; font-weight: 600; }

.extra-rm {
  width: 18px;
  height: 18px;
  display: inline-grid;
  place-items: center;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-full);
  background: var(--surface);
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
}

.extra-rm:hover { color: var(--danger); border-color: var(--danger); background: var(--danger-soft); }

.paid-overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  gap: 4px;
  justify-items: center;
  background: color-mix(in srgb, var(--surface) 82%, transparent);
  text-align: center;
}

.paid-text { font-size: 18px; font-weight: 600; letter-spacing: 0.08em; color: var(--success); }
.paid-method { font-size: 12px; color: var(--muted); }

.upsell-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); gap: 8px; margin: var(--space-3) 0 var(--space-4); }

.upsell-btn {
  display: grid;
  gap: 2px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: border-color var(--dur) var(--ease), background-color var(--dur) var(--ease);
}

.upsell-btn:hover { border-color: var(--line-strong); background: var(--subtle); }
.upsell-btn .n { font-size: 12px; font-weight: 500; }
.upsell-btn .p { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 11px; color: var(--muted); }

.pay-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }

.pay-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 14px;
  border: 1px solid var(--text);
  border-radius: var(--radius-md);
  background: var(--text);
  color: var(--surface);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: opacity var(--dur) var(--ease);
}

.pay-btn:hover { opacity: 0.88; }

/* Alternatives proposées (retard / conflit) : composant partagé dans pinlane.css */

.ops-plan-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: var(--space-2); margin-top: var(--space-2); }

.ops-plan-card {
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--page);
}

.ops-plan-card .k { color: var(--faint); font-size: 11px; font-weight: 500; margin-bottom: 4px; }
.ops-plan-card .v { color: var(--text); font-size: 12px; line-height: 1.4; }
.ops-checklist { display: grid; gap: 4px; font-size: 12px; color: var(--muted); }

/* Modale édition */
.edit-modal {
  width: min(880px, calc(100vw - 32px));
  max-height: calc(100dvh - 32px);
  display: flex;
  flex-direction: column;
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-overlay);
  overflow: hidden;
}

/* EN-TÊTE EN DEUX ÉTAGES : l'identité du dossier, puis les onglets. Les onglets
   étaient EMPILÉS SOUS le sous-titre à l'intérieur du même bloc, donc décalés
   au milieu de l'en-tête, sans filet ni alignement : rien ne disait qu'ils
   commandaient le corps en dessous. Ils courent maintenant sur toute la largeur,
   posés sur le filet qui sépare l'en-tête du corps. */
.edit-modal-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--space-3) var(--space-4);
  padding: var(--space-4) var(--space-5) 0;
  border-bottom: 1px solid var(--line);
}

.edit-modal-ident { min-width: 0; }
.modal-tabs { grid-column: 1 / -1; }
.edit-modal-head h3 { font-size: 18px; font-weight: 600; letter-spacing: -0.02em; line-height: 1.2; }
/* La ligne d'identité est une DONNÉE : heure, piste, effectif, montant. Geist
   Mono tabulaire pour les chiffres, séparateurs discrets, jamais de retour à la
   ligne au milieu d'une valeur. */
.edit-modal-head p {
  color: var(--muted);
  font-size: 13px;
  margin-top: 5px;
  font-variant-numeric: tabular-nums;
  line-height: 1.5;
}
/* Référence du dossier : une donnée, donc Geist Mono tabulaire (DESIGN.md §4).
   C'est le seul endroit de l'écran où elle s'affiche, et c'est voulu : on la
   lit quand on a le client au téléphone, pas quand on survole le planning. */
.edit-modal-head .pos-ref { font-family: var(--font-data); font-variant-numeric: tabular-nums; color: var(--text); font-weight: 500; }
.edit-modal-body { flex: 1; min-height: 0; overflow: auto; padding: var(--space-5); }

.edit-shell { display: grid; gap: var(--space-4); }
.edit-summary { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: var(--space-3); align-items: stretch; }

.edit-summary-card {
  padding: var(--space-4);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.edit-summary-card h4 { font-size: 15px; margin-top: 2px; }
.edit-summary-card p { color: var(--muted); font-size: 12px; margin-top: 4px; font-variant-numeric: tabular-nums; }

.edit-summary-stat {
  display: grid;
  gap: 2px;
  align-content: center;
  min-width: 90px;
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  text-align: center;
}

.edit-summary-stat .k { color: var(--muted); font-size: 11px; font-weight: 500; }
.edit-summary-stat .v { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 18px; font-weight: 600; }

.edit-form { display: grid; gap: var(--space-4); }
.edit-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--space-3); align-items: start; }
.edit-stack { display: grid; gap: var(--space-3); }
.edit-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3); }
.field-stack { display: grid; gap: var(--space-3); }

.edit-inline-note { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; }
.edit-inline-note .n { color: var(--muted); }
.edit-inline-note .v { font-weight: 500; }

/* Ce qui détruit à gauche, ce qui fait avancer à droite, et tout l'espace
   disponible entre les deux : c'est la protection du clic accidentel, et elle
   ne coûte ni fenêtre de confirmation supplémentaire ni double clic. */
.edit-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
  padding-top: var(--space-3);
  border-top: 1px solid var(--line);
}

.edit-actions-destructive,
.edit-actions-main { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }

.edit-actions .btn-secondary,
.edit-actions .btn-primary,
.step-actions .btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 36px;
  padding: 0 14px;
  border-radius: var(--radius-sm);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), opacity var(--dur) var(--ease);
}

.edit-actions .btn-secondary { border: 1px solid var(--line-strong); background: var(--surface); color: var(--text); }
.edit-actions .btn-secondary:hover { background: var(--subtle); }
.edit-actions .btn-secondary.warn { color: var(--warning); }
.edit-actions .btn-secondary.warn:hover { background: var(--warning-soft); border-color: var(--warning); }
.edit-actions .btn-secondary.danger { color: var(--danger); }
.edit-actions .btn-secondary.danger:hover { background: var(--danger-soft); border-color: var(--danger); }
.edit-actions .btn-primary { border: 1px solid var(--text); background: var(--text); color: var(--surface); }
.edit-actions .btn-primary:hover { opacity: 0.88; }

/* ============================================================================
   LA FICHE DE RESERVATION (« Infos » et « Modifier ») - refonte 2026-08-14.

   CINQ blocs au meme poids ne font pas une hierarchie, ils font une liste. La
   fiche empilait cinq cartes identiques (meme fond, meme bordure, meme titre en
   600) : rien ne disait par quoi commencer, et le premier bloc - le plus
   visible - recopiait mot pour mot le sous-titre de l'en-tete.

   DEUX POIDS SUFFISENT, et c'est la seule regle de cette section :
     - UNE surface se souleve, celle de l'action (fond + bordure + ombre courte) ;
     - tout le reste est PLAT et se separe par un filet.
   Aucune couleur ajoutee, aucun encadrement supplementaire : le rang se lit a
   la profondeur, exactement comme sur les cartes du planning.
   ========================================================================== */

.pos-sheet { display: grid; gap: var(--space-4); }

/* Les blocs reutilises (checklist d'activites, programme du groupe, plan
   automatique) gardent leur balisage : c'est leur HABILLAGE qui change, et
   seulement dans la fiche. Le selecteur est scope pour que la carte Formules,
   qui rend la meme checklist ailleurs, ne bouge pas d'un pixel. */
.pos-sheet .info-block {
  margin-bottom: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: none;
}

/* Seuls les groupes de PREMIER rang portent le filet qui les separe. Un bloc
   imbrique (la checklist dans un programme, un groupe de champs dans une
   colonne) n'a pas a redessiner une frontiere que son parent trace deja. */
.pos-sheet > .info-block {
  padding-top: var(--space-4);
  border-top: 1px solid var(--line);
}

/* L'intitule de groupe descend d'un rang : il n'a plus a rivaliser avec le
   titre du dossier, il n'a qu'a nommer ce qui suit. Capitales, interlettrage
   ouvert, `--muted` (5,7:1 en clair, AA large). */
.pos-sheet .info-label {
  display: block;
  margin-bottom: var(--space-3);
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pos-group-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
}

.pos-group-head .info-label { margin-bottom: 0; }

/* LE BLOC D'ACTION. Seule surface soulevee de la fiche, et premiere chose que
   le corps dit : l'en-tete a deja repondu qui, quand, ou et combien. */
.pos-act {
  padding: var(--space-4);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}

.pos-act-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-3);
  flex-wrap: wrap;
  margin-bottom: var(--space-3);
}

.pos-eyebrow {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* Le reste a encaisser etait la SEULE donnee du bloc « Resume » absente de
   l'en-tete, et il vivait tout en bas de la fiche. Il remonte a cote des
   boutons d'etat : c'est la, et nulle part ailleurs, qu'on s'en sert. */
.pos-act-money {
  color: var(--muted);
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-size: 12px;
}

.pos-act-money b { color: var(--text); font-weight: 600; }
.pos-act-money.is-paid { color: var(--success); }

/* Les trois etats deviennent un vrai selecteur segmente : parts egales, cible
   confortable. La pastille qui les doublait a 8 px de la est retiree - un
   bouton actif DIT deja l'etat, l'ecrire deux fois n'informe personne. */
.pos-act-row { gap: var(--space-2); }
.pos-act-row .res-status-btn {
  flex: 1 1 0;
  min-height: 36px;
  font-size: 13px;
}

.pos-contact { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-5); }

.pos-contact-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
}

.pos-contact-item svg { flex: none; color: var(--muted); }

.pos-note {
  margin-bottom: var(--space-3);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

/* LE RETARD SE REPLIE. Six controles permanents pour une action occasionnelle
   qui ouvre de toute facon sa propre fenetre : ils passent derriere un
   depliant natif (clavier et synthese vocale gratuits, zero JavaScript). Rien
   n'est retire, et le depliant s'ouvre TOUT SEUL quand le client est deja en
   retard, c'est-a-dire au seul moment ou ces boutons servent. */
.pos-fold > summary {
  list-style: none;
  cursor: pointer;
  user-select: none;
}

.pos-fold > summary::-webkit-details-marker { display: none; }
.pos-fold > summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }
.pos-fold-chevron { color: var(--muted); transition: transform var(--dur) var(--ease-out-strong); }
.pos-fold[open] > summary .pos-fold-chevron { transform: rotate(180deg); }

.pos-plan-list { display: grid; }

.pos-plan-row {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
  font-size: 13px;
}

.pos-plan-row:last-child { border-bottom: 0; }
.pos-plan-label { color: var(--text); font-weight: 600; }
.pos-plan-time { color: var(--muted); font-family: var(--font-data); font-variant-numeric: tabular-nums; }

/* CHAMPS : intitule au-dessus, aide en dessous, et l'erreur ne se declare
   qu'apres que la personne a touche le champ (`:user-invalid`). `:invalid`
   seul allume tous les champs obligatoires des l'ouverture : un ecran rouge
   avant la premiere frappe apprend a ignorer le rouge. */
.pos-field { display: grid; gap: 6px; align-content: start; }
.pos-field-wide { grid-column: 1 / -1; }
.pos-field .lbl { font-size: 11px; color: var(--muted); font-weight: 500; }
.pos-field .field-hint { margin-top: 2px; line-height: 1.45; }

/* Le contenu reel d'une formule dans la fiche de modification. Une liste,
   parce que c'en est une : le staff scanne les lignes au lieu de lire une
   phrase qui les enfile. */
.edit-formule-list {
  margin: 4px 0 0;
  padding-left: 16px;
  display: grid;
  gap: 2px;
  font-size: 13px;
  line-height: 1.45;
  color: var(--text-2, #4b5563);
}
.edit-formule-list li { list-style: disc; }

/* Le motif d'un enregistrement refuse. Il vit DANS la fiche, au-dessus des
   boutons, la ou le regard va apres avoir clique : un toast qui s'efface
   laisse le staff devant un ecran qui ne correspond plus a la base. */
.edit-error {
  margin: 0 0 10px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--danger-border, #7f1d1d);
  background: var(--danger-soft, rgba(153, 27, 27, 0.16));
  color: var(--danger-text, #fca5a5);
  font-size: 13px;
  line-height: 1.45;
}
.edit-error[hidden] { display: none; }
.pos-field .input:user-invalid { border-color: var(--danger); box-shadow: 0 0 0 3px var(--danger-soft); }

/* Un bouton doit repondre au doigt. 100-160 ms, `transform` uniquement, et
   l'enfoncement ne se joue que la ou un curseur existe. */
.pos-sheet .res-status-btn,
.pos-sheet .delay-chip,
.pos-sheet .comm-open-btn,
.edit-actions .btn-secondary,
.edit-actions .btn-primary {
  transition: background-color var(--dur) var(--ease), border-color var(--dur) var(--ease), color var(--dur) var(--ease), opacity var(--dur) var(--ease), transform 120ms var(--ease-out-strong);
}

@media (hover: hover) and (pointer: fine) {
  .pos-sheet .res-status-btn:active,
  .pos-sheet .delay-chip:active,
  .pos-sheet .comm-open-btn:active,
  .edit-actions .btn-secondary:active,
  .edit-actions .btn-primary:active { transform: scale(0.97); }
}

@media (prefers-reduced-motion: reduce) {
  .pos-fold-chevron,
  .pos-sheet .res-status-btn,
  .pos-sheet .delay-chip,
  .pos-sheet .comm-open-btn,
  .edit-actions .btn-secondary,
  .edit-actions .btn-primary { transition: none; }
}

/* Réservation rapide (quick book) */
.qb-overlay {
  position: fixed;
  inset: 0;
  z-index: 430;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  background: var(--scrim);
}

.qb-overlay.hidden { display: none; } /* le JS remplace className : on regarantit l'état caché */

.qb-modal {
  width: min(760px, calc(100vw - 24px));
  max-height: calc(100dvh - 28px);
  overflow-y: auto;
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-overlay);
}

.qb-head {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-4) var(--space-5);
  border-bottom: 1px solid var(--line);
  background: var(--raised);
}

.qb-head h3 { font-size: 17px; }
.qb-head .sub { font-size: 12px; color: var(--muted); margin-top: 2px; }

.qb-body { padding: var(--space-4) var(--space-5); display: flex; flex-direction: column; gap: var(--space-3); }

.qb-block {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  padding: var(--space-3);
}

.blk-label { font-size: 12px; color: var(--muted); font-weight: 500; margin-bottom: 8px; }

.qb-row { display: grid; gap: 8px; }
.qb-row.three { grid-template-columns: 1.2fr 1fr 1fr; }
.qb-mini-label { display: block; font-size: 11px; color: var(--muted); font-weight: 500; margin-bottom: 4px; }

.qb-input {
  width: 100%;
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-ui);
  font-size: 13px;
}

.qb-input-invalid { border-color: var(--danger); background: var(--danger-soft); }
.qb-textarea { height: auto; min-height: 52px; padding: 8px 10px; line-height: 1.4; resize: vertical; }


/* Aide courte sous un champ ou un titre de section « Plus d'options ». */
.qb-field-note { margin-top: 4px; font-size: 11px; color: var(--muted); }
.qb-field-note.danger { color: var(--danger); }
.qb-block-help { margin: -2px 0 10px; font-size: 11.5px; color: var(--muted); line-height: 1.4; }

/* Le conteneur ne dispose plus rien lui-meme : il porte desormais DEUX blocs
   (la grille des activites et la rangee des modes), et une grille parent les
   aurait mis cote a cote au lieu de les empiler. */
.qb-type-row { display: block; margin-bottom: 10px; }

.qb-type-btn {
  min-height: 36px;
  padding: 0 10px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), border-color var(--dur) var(--ease), color var(--dur) var(--ease);
}

.qb-type-btn:hover { background: var(--subtle); color: var(--text); }
.qb-type-btn.active { background: var(--accent-soft); border-color: var(--accent); color: var(--accent-strong); }

.qb-snapshot-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-bottom: 10px; }

.qb-snapshot {
  display: grid;
  gap: 2px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--page);
}

.qb-snapshot .k { font-size: 11px; color: var(--muted); font-weight: 500; }
.qb-snapshot .v { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 13px; font-weight: 600; }
.qb-snapshot .t { font-size: 11px; color: var(--faint); }

.qb-inline-actions, .qb-action-stack { display: flex; gap: 6px; flex-wrap: wrap; }

.qb-ghost-btn {
  min-height: 28px;
  padding: 0 10px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease);
}

.qb-ghost-btn:hover { background: var(--accent-soft); }
.qb-section-note { font-size: 12px; color: var(--faint); }

.qb-formule-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 8px; margin-top: 6px; }

.qb-formule-card {
  display: grid;
  gap: 5px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: border-color var(--dur) var(--ease), background-color var(--dur) var(--ease);
}

.qb-formule-card:hover { border-color: var(--line-strong); }
.qb-formule-card.active { border-color: var(--accent); background: var(--accent-soft); }
.qb-formule-card.unavailable { opacity: 0.55; cursor: not-allowed; }

.qb-formule-top { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; }
.qb-formule-name { font-size: 13px; font-weight: 600; }
.qb-formule-price { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 12px; font-weight: 500; white-space: nowrap; }
.qb-formule-sub { font-size: 11px; color: var(--muted); }
.qb-formule-status { display: flex; align-items: center; gap: 6px; }

.qb-status-pill {
  padding: 0 8px;
  border-radius: var(--radius-full);
  font-size: 10px;
  font-weight: 500;
  line-height: 1.8;
}

.qb-status-pill.ok { background: var(--success-soft); color: var(--success); }
.qb-status-pill.no { background: var(--danger-soft); color: var(--danger); }
.qb-inline-note { font-size: 11px; color: var(--faint); }

.qb-slot-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-bottom: 6px; }
.qb-slot-strip { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 8px; }

.qb-slot-chip {
  display: grid;
  gap: 2px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: border-color var(--dur) var(--ease), background-color var(--dur) var(--ease);
}

.qb-slot-chip:hover { border-color: var(--line-strong); }
.qb-slot-chip.active { border-color: var(--accent); background: var(--accent-soft); }
.qb-slot-chip.locked { cursor: default; }
.qb-slot-chip .time { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 14px; font-weight: 600; }
.qb-slot-chip .sub { font-size: 11px; color: var(--muted); }
.qb-slot-chip .lanes { font-size: 10px; color: var(--faint); }
.qb-slot-chip.active .lanes { color: var(--accent-strong); }

.qb-empty-note { padding: var(--space-3); border: 1px dashed var(--line-strong); border-radius: var(--radius-md); color: var(--muted); font-size: 12px; text-align: center; }

/* Variantes contextuelles : rappel des acquis (jamais redemandés) */
.qb-row.two { grid-template-columns: 1.2fr 1fr; }
.qb-row.auto { grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); }

.qb-context-strip { display: flex; flex-wrap: wrap; gap: 8px; }

.qb-context-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--page);
}

.qb-context-chip .k { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: var(--faint); }
.qb-context-chip .v { font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; }

.qb-chip-edit {
  border: none;
  background: transparent;
  padding: 2px 0 0;
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  align-self: flex-end;
}

.qb-chip-edit:hover { text-decoration: underline; }
.qb-chip-lock { font-size: 10px; color: var(--faint); align-self: flex-end; padding-bottom: 2px; }

.qb-status-line { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 10px; font-size: 12px; color: var(--muted); }
.qb-status-line span + span::before { content: '·'; margin-right: 14px; color: var(--faint); }

.qb-more-toggle {
  width: 100%;
  min-height: 34px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), color var(--dur) var(--ease);
}

.qb-more-toggle:hover { background: var(--subtle); color: var(--text); }
.qb-more-toggle[aria-expanded="true"] { color: var(--text); }

.qb-dur-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(90px, 1fr)); gap: 6px; }

.qb-dur-btn {
  display: grid;
  gap: 1px;
  justify-items: center;
  align-content: center;
  min-height: 36px;
  padding: 5px 8px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.2;
  text-align: center;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), border-color var(--dur) var(--ease);
}

.qb-dur-btn small { font-size: 10px; color: var(--faint); font-weight: 400; }
.qb-dur-btn:hover { background: var(--subtle); }
.qb-dur-btn.active { border-color: var(--accent); background: var(--accent-soft); color: var(--accent-strong); }

.qb-lane-focus {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-3);
  flex-wrap: wrap;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--page);
  margin-bottom: 10px;
}

.qb-lane-focus-title { font-size: 13px; font-weight: 600; }
.qb-lane-focus-sub { font-size: 11px; color: var(--muted); margin-top: 2px; }

.qb-lane-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(44px, 1fr)); gap: 6px; }

.qb-lane-btn {
  min-height: 36px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), border-color var(--dur) var(--ease);
}

.qb-lane-btn:hover { background: var(--subtle); }
.qb-lane-btn.auto { font-family: var(--font-ui); }
.qb-lane-btn.active { border-color: var(--accent); background: var(--accent-soft); color: var(--accent-strong); }
.qb-lane-btn.suggested { border-style: dashed; border-color: var(--accent); }
.qb-lane-btn.busy, .qb-lane-btn.maint { opacity: 0.45; cursor: not-allowed; }

.qb-lane-footer { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-top: 8px; }
.qb-lane-selection { font-size: 12px; color: var(--muted); }

.qb-warn {
  padding: 8px 11px;
  border-radius: var(--radius-sm);
  background: var(--warning-soft);
  color: var(--warning);
  font-size: 12px;
  line-height: 1.45;
}

.qb-warn.danger { background: var(--danger-soft); color: var(--danger); }

.qb-summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.qb-summary .lbl { font-size: 12px; color: var(--muted); font-weight: 500; }
.qb-summary .desc { font-size: 12px; color: var(--faint); margin-top: 2px; }
.qb-summary .amt { font-family: var(--font-data); font-variant-numeric: tabular-nums; font-size: 22px; font-weight: 600; }

.qb-actions {
  position: sticky;
  bottom: 0;
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  padding: var(--space-4) var(--space-5);
  border-top: 1px solid var(--line);
  background: var(--raised);
}

.qb-btn-cancel {
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.qb-btn-cancel:hover { background: var(--subtle); }

.qb-btn-save {
  min-height: 36px;
  padding: 0 16px;
  border: 1px solid var(--text);
  border-radius: var(--radius-sm);
  background: var(--text);
  color: var(--surface);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: opacity var(--dur) var(--ease);
}

.qb-btn-save:hover { opacity: 0.88; }

/* ── RESERVER : LA FENETRE UNIQUE (v5, lot I2, 2026-10-08) ──────────────────
   Movsar sur les maquettes : une ligne compacte par activite (« tout se lit
   d un regard »), le detail au toucher, aucun plafond (« on est le staff »),
   placement Auto ou Choisir, l horloge qui dit ce qui tient pour CE groupe,
   le verdict du planning avant la creation, le billet toujours visible, et
   plusieurs resas pour un meme client. A gauche la composition, a droite le
   billet ; au telephone une colonne et le bouton colle en bas.
   Couleurs : uniquement les jetons (pinlane.css), les activites comprises
   (--act-*). --rv-c porte la couleur de la ligne, posee en style par ligne. */
.qb-overlay.is-rv { padding: 16px; }

.qb-modal.rv {
  --rv-c: var(--accent);
  --rv-vide: var(--line);
  --rv-fond-billet: var(--page);
  --rv-voile: color-mix(in srgb, var(--accent) 7%, var(--surface));
  --rv-autres: color-mix(in srgb, var(--muted) 45%, transparent);
  --rv-cases: 30;
  --rv-pistes: 8;
  --rv-origine: top right;
  position: relative;
  width: min(1216px, 100%);
  height: min(780px, calc(100dvh - 32px));
  max-height: none;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  overflow: hidden;
  padding: 0;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 22px;
  font-size: 14px;
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
}
.qb-modal.rv button { font: inherit; color: inherit; cursor: pointer; }
.qb-modal.rv button:disabled { cursor: default; }
.qb-modal.rv svg { flex: none; }
.qb-modal.rv :focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.rv-zone-contenu { display: contents; }
.rv-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.rv-compo { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; }

/* LA TETE : le jour d abord, c est la premiere question au telephone */
.rv-tete { display: flex; align-items: center; gap: 6px; height: 64px; padding: 0 14px 0 20px; border-bottom: 1px solid var(--line); flex: none; }
.rv-tete h3 { margin: 0 12px 0 0; min-width: 0; flex: none; max-width: 46%; overflow: hidden; text-overflow: ellipsis; font-size: 20px; font-weight: 720; letter-spacing: -.02em; white-space: nowrap; }
.rv-jours { display: flex; gap: 6px; min-width: 0; flex: 0 1 auto; overflow-x: auto; scrollbar-width: none; }
.rv-jour { position: relative; height: 36px; padding: 0 11px; border-radius: 999px; border: 1px solid var(--line-strong); background: transparent; font-size: 13px; font-weight: 600; color: var(--muted); white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; }
.rv-jour small { font-size: 11.5px; font-weight: 500; color: var(--faint); }
.rv-jour.is-on { background: var(--accent); border-color: var(--accent); color: var(--accent-contrast); }
.rv-jour.is-on small { color: color-mix(in srgb, var(--accent-contrast) 80%, transparent); }
.rv-jour svg { width: 15px; height: 15px; }
.rv-jour input[type='date'] { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; border: 0; padding: 0; }
.rv-tete .rv-droite { margin-left: auto; flex: none; display: flex; align-items: center; gap: 6px; }
.rv-rond { width: 36px; height: 36px; padding: 0; border-radius: 50%; border: 1px solid var(--line-strong); background: transparent; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; }
.rv-rond.close-btn { font-size: 19px; font-weight: 500; }
.rv-rond.is-on { background: var(--accent-soft); border-color: var(--accent); color: var(--accent-strong); }

/* COMBIEN */
.rv-joueurs { display: flex; align-items: center; gap: 14px; padding: 12px 22px; border-bottom: 1px solid var(--line); flex: none; }
.rv-etq { font-size: 11px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--faint); }
.rv-stepper { display: inline-flex; align-items: center; height: 52px; border-radius: 15px; background: var(--raised); border: 1px solid var(--line); }
.rv-stepper button { width: 44px; height: 100%; padding: 0; border: 0; background: transparent; color: var(--muted); font-size: 22px; line-height: 1; }
.rv-stepper input { width: 64px; height: 100%; padding: 0; border: 0; background: transparent; color: var(--text); text-align: right; font: 760 30px/1 var(--font-ui); letter-spacing: -.04em; font-variant-numeric: tabular-nums; -moz-appearance: textfield; appearance: textfield; }
.rv-stepper input::-webkit-outer-spin-button, .rv-stepper input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.rv-stepper input:focus-visible { outline: none; }
.rv-stepper:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent); }
.rv-stepper .rv-suf { margin: 8px 8px 0 7px; font-size: 12.5px; font-weight: 600; color: var(--muted); }
.rv-tailles { display: flex; gap: 5px; flex: none; }
.rv-tailles button { min-width: 38px; height: 36px; padding: 0 8px; border-radius: 10px; border: 1px solid var(--line); background: transparent; color: var(--muted); font-size: 14px; font-weight: 650; }
.rv-tailles button.is-on { background: var(--accent-soft); border-color: var(--accent); color: var(--accent-strong); }
.rv-consequence { margin-left: auto; min-width: 0; text-align: right; font-size: 12.5px; line-height: 1.45; color: var(--muted); }
.rv-consequence b { color: var(--text); font-weight: 650; }

/* LE PLAN */
.qb-modal.rv .rv-plan { flex: 1; min-height: 0; overflow: auto; padding: 14px 22px; display: flex; flex-direction: column; gap: 9px; }
.rv-plan-tete { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.rv-seg { display: inline-flex; padding: 3px; border-radius: 999px; background: var(--subtle); border: 1px solid var(--line); }
.rv-seg button { min-height: 30px; padding: 0 12px; border: 0; border-radius: 999px; background: transparent; font-size: 12.5px; font-weight: 650; color: var(--muted); white-space: nowrap; }
.rv-seg button.is-on { background: var(--raised); color: var(--text); box-shadow: 0 0 0 1px var(--line-strong) inset, var(--shadow-sm); }
.rv-plan-tete .rv-dr { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; }
.rv-puce { height: 30px; padding: 0 11px; border-radius: 999px; border: 1px solid var(--line); background: transparent; font-size: 12.5px; font-weight: 600; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.rv-puce svg { width: 14px; height: 14px; }
.rv-puce b { color: var(--text); font-weight: 650; }
.rv-puce.is-on { border-color: var(--accent); background: var(--rv-voile); color: var(--text); }

/* Les departs rapides et les formules : des tuiles */
.rv-departs { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.rv-depart { position: relative; text-align: left; padding: 11px 12px 12px; border-radius: 14px; border: 1px solid var(--line); background: var(--raised); display: flex; flex-direction: column; gap: 6px; min-width: 0; }
div.rv-depart { padding: 0; }
.rv-depart-btn { width: 100%; padding: 11px 34px 12px 12px; border: 0; border-radius: 14px; background: transparent; text-align: left; display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.rv-depart .rv-pts { display: flex; gap: 4px; min-height: 6px; }
.rv-depart .rv-pts i { width: 18px; height: 6px; border-radius: 3px; background: var(--rv-c); }
.rv-depart b { font-size: 14px; font-weight: 700; }
.rv-depart span { font-size: 12px; color: var(--muted); }
.rv-depart em { font-style: normal; font-size: 11.5px; color: var(--warning); }
.rv-depart.is-on { border-color: var(--accent); background: var(--rv-voile); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent); }
.rv-depart.is-hors b { color: var(--muted); }
.rv-epingle { position: absolute; top: 7px; right: 7px; width: 26px; height: 26px; padding: 0; border-radius: 8px; border: 0; background: transparent; color: var(--faint); display: inline-flex; align-items: center; justify-content: center; }
.rv-epingle svg { width: 13px; height: 13px; }
.rv-epingle.is-on { color: var(--accent-strong); }
.rv-departs-pied { font-size: 12px; color: var(--muted); }

/* UNE LIGNE PAR ACTIVITE : tout d un regard, le detail au chevron */
.rv-lc { --rv-c: var(--accent); position: relative; border: 1px solid var(--line); border-radius: 16px; background: var(--raised); }
.rv-lc::before { content: ''; position: absolute; left: -1px; top: 16px; height: 30px; width: 3px; border-radius: 0 3px 3px 0; background: var(--rv-c); }
.rv-lc-h { display: grid; grid-template-columns: 124px 200px 120px 112px minmax(0, 1fr) 34px 28px; align-items: center; column-gap: 8px; min-height: 60px; padding: 8px 8px 8px 18px; }
.rv-lc-h > * { justify-self: start; min-width: 0; }
.rv-lc-h .rv-etat-l { justify-self: end; }
.rv-lc.is-ouverte { border-color: color-mix(in srgb, var(--rv-c) 55%, var(--line)); box-shadow: 0 0 0 3px color-mix(in srgb, var(--rv-c) 12%, transparent); }
.rv-lc.is-ko { border-color: color-mix(in srgb, var(--danger) 55%, var(--line)); }
.rv-nom { display: flex; align-items: center; gap: 9px; font-size: 15px; font-weight: 690; letter-spacing: -.01em; line-height: 1.2; max-width: 100%; }
.rv-nom > span { overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow-wrap: anywhere; }
.rv-pt { width: 10px; height: 10px; border-radius: 3.5px; background: var(--rv-c); flex: none; }
.rv-qte { display: inline-flex; align-items: center; height: 44px; border-radius: 12px; border: 1px solid var(--line); background: var(--surface); }
.rv-qte button { width: 44px; height: 100%; padding: 0; border: 0; background: transparent; color: var(--muted); font-size: 19px; line-height: 1; }
.rv-qte button:disabled { opacity: .35; }
.rv-qte b { min-width: 20px; text-align: center; font-size: 16px; font-weight: 750; letter-spacing: -.01em; white-space: nowrap; }
.rv-qte > span { margin: 1px 2px 0 4px; font-size: 12.5px; font-weight: 600; color: var(--muted); white-space: nowrap; }
.rv-qte-fixe { font-size: 14px; font-weight: 650; color: var(--muted); white-space: nowrap; }
.rv-heure-wrap { position: relative; }
.rv-heure { height: 44px; padding: 0 10px 0 9px; border-radius: 12px; border: 1px solid var(--line-strong); background: var(--surface); display: inline-flex; align-items: center; gap: 8px; font-size: 16px; font-weight: 740; letter-spacing: -.02em; white-space: nowrap; }
.rv-heure svg { width: 17px; height: 17px; color: var(--accent-strong); }
.rv-heure small { font-size: 11.5px; font-weight: 600; letter-spacing: 0; color: var(--muted); }
.rv-heure.is-ouvert { border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 25%, transparent); }
.rv-heure.is-ko { border-color: var(--danger); color: var(--danger); }
.rv-heure.is-ko svg { color: var(--danger); }
.rv-heure.is-foulee svg { color: var(--muted); }
.rv-heure.is-libre { border-style: dashed; color: var(--muted); font-size: 13px; font-weight: 600; letter-spacing: 0; }
.rv-heure:disabled { opacity: .7; }
.rv-place { height: 44px; padding: 0 11px; border-radius: 12px; border: 1px dashed var(--line-strong); background: transparent; font-size: 12.5px; font-weight: 650; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; max-width: 100%; overflow: hidden; }
.rv-place svg { width: 14px; height: 14px; }
.rv-place b { color: var(--text); font-weight: 700; overflow: hidden; text-overflow: ellipsis; }
.rv-place.is-manuel { border-style: solid; border-color: color-mix(in srgb, var(--rv-c) 65%, transparent); background: color-mix(in srgb, var(--rv-c) 12%, transparent); color: var(--text); }
.rv-etat-l { display: inline-flex; flex-direction: column; align-items: flex-end; gap: 5px; font-size: 12.5px; line-height: 1.3; color: var(--muted); text-align: right; max-width: 100%; }
.rv-etat-l > span:last-child { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; overflow: hidden; max-width: 100%; }
.rv-etat-l b { color: var(--text); font-weight: 650; }
.rv-ok { color: var(--success); font-weight: 650; }
.rv-att { color: var(--warning); font-weight: 650; }
.rv-ko { color: var(--danger); font-weight: 650; }
.rv-barre-l { display: flex; width: 92px; height: 5px; border-radius: 3px; background: var(--rv-vide); overflow: hidden; }
.rv-barre-l i { display: block; height: 100%; }
.rv-barre-l i.is-autres { background: var(--rv-autres); }
.rv-barre-l i.is-nous { background: var(--rv-c); }
.rv-ouvrir { width: 34px; height: 34px; padding: 0; border-radius: 10px; border: 1px solid var(--line); background: transparent; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; flex: none; }
.rv-ouvrir svg { width: 16px; height: 16px; transition: transform var(--dur) var(--ease-out-strong); }
.rv-lc.is-ouverte .rv-ouvrir { background: var(--surface); color: var(--text); }
.rv-lc.is-ouverte .rv-ouvrir svg { transform: rotate(180deg); }

.rv-lc-d .rv-seg button { min-height: 40px; padding: 0 14px; }
.rv-lc-d { border-top: 1px solid var(--line); padding: 10px 14px 12px 18px; display: flex; flex-direction: column; gap: 8px; }
.rv-rg { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.rv-lbl { min-width: 78px; font-size: 12px; font-weight: 650; color: var(--faint); }
.rv-note-r { font-size: 12px; color: var(--muted); }
.rv-note-r b { color: var(--text); font-weight: 650; }
.rv-pr { display: grid; grid-template-columns: 78px 104px minmax(0, 1fr) auto 30px; align-items: center; gap: 12px; font-size: 12.5px; color: var(--muted); }
.rv-pr .rv-p { font-size: 13px; font-weight: 650; color: var(--text); }
.rv-pr .rv-heure { height: 40px; font-size: 15px; padding: 0 10px 0 9px; border-radius: 10px; }
.rv-pr .rv-heure svg { width: 15px; height: 15px; }
.rv-pr .rv-cpt { white-space: nowrap; }
.rv-pr .rv-cpt b { color: var(--text); }
.rv-x1 { width: 30px; height: 30px; padding: 0; border: 0; border-radius: 8px; background: transparent; color: var(--faint); font-size: 18px; line-height: 1; }
.rv-x1.rv-retirer { width: 28px; height: 28px; position: relative; }
.rv-x1.rv-retirer::before { content: '×'; font-size: 18px; line-height: 28px; }
.rv-x1:hover { color: var(--text); background: var(--overlay-hover); }
/* Le compteur d une activite libre tient dans la ligne compacte : sa legende
   (Joueurs, Enfants) reste lue par les lecteurs d ecran et par la ligne. */
.rv-lc-h .qb-visit-compteur { display: inline-flex; align-items: center; gap: 6px; margin: 0; padding: 0; border: 0; background: transparent; }
.rv-lc-h .qb-visit-compteur .qb-opt-legend { font-size: 11px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--faint); }
.rv-lc-h .qb-visit-compteur .staff-stepper { height: 44px; border-radius: 12px; border: 1px solid var(--line); background: var(--surface); display: inline-flex; align-items: center; }
.rv-lc-h .qb-visit-compteur .qb-step-btn { width: 44px; height: 44px; padding: 0; border: 0; border-radius: 12px; background: transparent; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; }
.rv-lc-h .qb-visit-compteur .qb-step-valeur { min-width: 44px; text-align: center; font-size: 14px; font-weight: 750; white-space: nowrap; }
.rv-lc-d .qb-visit-options { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin: 0; }
.rv-lc-d .qb-opt-legend { min-width: 78px; font-size: 12px; font-weight: 650; color: var(--faint); }
.rv-lc-d .qb-dur-btn { min-height: 44px; padding: 0 11px; border-radius: 999px; border: 1px solid var(--line); background: transparent; font-size: 12.5px; font-weight: 650; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; }
.rv-lc-d .qb-dur-btn small { font-size: 11px; color: var(--faint); }
.rv-lc-d .qb-dur-btn.active, .rv-lc-d .qb-dur-btn.is-on { border-color: color-mix(in srgb, var(--rv-c) 70%, transparent); background: color-mix(in srgb, var(--rv-c) 14%, transparent); color: var(--text); }
.rv-lc-d .staff-stepper { height: 44px; border-radius: 12px; border: 1px solid var(--line); background: var(--surface); display: inline-flex; align-items: center; }
.rv-lc-d .qb-step-btn { width: 44px; height: 44px; padding: 0; border: 0; border-radius: 12px; background: transparent; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; }
.rv-lc-d .qb-step-valeur { min-width: 52px; text-align: center; font-size: 13.5px; font-weight: 700; }
.rv-lc-d .qb-visit-compteur { display: inline-flex; align-items: center; gap: 8px; margin: 0; padding: 0; border: 0; background: transparent; }
.rv-lc-d .rv-rg .qb-visit-compteur .qb-opt-legend { display: none; }
.rv-pause { display: grid; grid-template-columns: 78px 1fr auto; align-items: center; gap: 12px; padding: 3px 10px 3px 0; border-radius: 10px; font-size: 12.5px; color: var(--muted); background: repeating-linear-gradient(135deg, transparent 0 6px, color-mix(in srgb, var(--line) 70%, transparent) 6px 7px); }
.rv-pause .rv-p { font-size: 13px; font-weight: 650; color: var(--text); }
.rv-pause .rv-x1 { width: 26px; height: 26px; }
.rv-jauge { display: grid; grid-template-columns: repeat(var(--rv-cases, 30), 1fr); gap: 2px; height: 12px; min-width: 120px; }
.rv-jauge i { border-radius: 2px; background: var(--rv-vide); }
.rv-jauge i.is-autres { background: var(--rv-autres); }
.rv-jauge i.is-nous { background: var(--rv-c); }
.rv-jauge i.is-trop { background: var(--danger); }
.rv-ajouts-l { display: flex; gap: 6px; flex-wrap: wrap; }
.rv-ajouts-l button { height: 30px; padding: 0 11px; border-radius: 999px; border: 1px dashed var(--line-strong); background: transparent; font-size: 12.5px; font-weight: 600; color: var(--muted); }
.rv-hors { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: 12px; background: var(--warning-soft); border: 1px solid color-mix(in srgb, var(--warning) 30%, transparent); font-size: 12.5px; line-height: 1.4; color: var(--text); }
.rv-hors .rv-ic { width: 20px; height: 20px; border-radius: 50%; background: var(--warning); color: var(--surface); font-size: 12px; font-weight: 800; display: inline-flex; align-items: center; justify-content: center; flex: none; }
.rv-hors span { color: var(--muted); }
.rv-hors b { color: var(--text); font-weight: 650; }
.rv-hors button { margin-left: auto; height: 30px; padding: 0 11px; border-radius: 999px; border: 1px solid var(--line-strong); background: var(--surface); font-size: 12.5px; font-weight: 650; color: var(--accent-strong); white-space: nowrap; }
.rv-pistes-choix { display: grid; grid-template-columns: repeat(var(--rv-pistes, 8), minmax(0, 1fr)); gap: 6px; }
.rv-pc { min-height: 64px; border-radius: 12px; border: 1px solid var(--line); background: var(--raised); padding: 8px 6px 7px; display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center; min-width: 0; }
.rv-pc b { font-size: 17px; font-weight: 760; }
.rv-pc .rv-occ { position: relative; width: 100%; height: 6px; border-radius: 3px; background: color-mix(in srgb, var(--success) 35%, var(--rv-vide)); overflow: hidden; }
.rv-pc .rv-occ i { position: absolute; top: 0; bottom: 0; left: 0; background: repeating-linear-gradient(135deg, color-mix(in srgb, var(--danger) 70%, transparent) 0 3px, transparent 3px 6px), color-mix(in srgb, var(--danger) 18%, var(--rv-vide)); }
.rv-pc small { font-size: 10.5px; line-height: 1.25; color: var(--muted); }
.rv-pc.is-on { border-color: var(--rv-c); background: color-mix(in srgb, var(--rv-c) 14%, var(--raised)); box-shadow: 0 0 0 3px color-mix(in srgb, var(--rv-c) 18%, transparent); }
.rv-pc.is-on small { color: var(--text); font-weight: 650; }
.rv-pc.is-on .rv-occ { background: var(--rv-c); }
.rv-pc.is-pris b { color: var(--faint); }
.rv-pc.is-maint { opacity: .55; }
.rv-pc.is-suggeree { border-style: dashed; border-color: color-mix(in srgb, var(--rv-c) 60%, var(--line)); }
.rv-options-autres .qb-visit-option, .rv-options-autres > * { max-width: 100%; }

.rv-lien { display: flex; align-items: center; gap: 8px; margin: -2px 0 -2px 26px; font-size: 12px; color: var(--muted); }
.rv-lien::before { content: ''; width: 2px; height: 22px; border-radius: 2px; background: repeating-linear-gradient(180deg, var(--line-strong) 0 4px, transparent 4px 7px); margin-right: 6px; }
.rv-lien svg { width: 14px; height: 14px; color: var(--accent-strong); }
