#staffEmailsPage .pv2-thread-question b { font-weight: 600; }
#staffEmailsPage .pv2-thread-events { margin-top: 6px; flex: 1 1 100%; }
#staffEmailsPage .pv2-thread-events summary { cursor: pointer; font-size: 12px; color: var(--muted); list-style: none; display: inline-flex; align-items: center; gap: 6px; }
#staffEmailsPage .pv2-thread-events summary::-webkit-details-marker { display: none; }
#staffEmailsPage .pv2-thread-events ul { list-style: none; margin: 6px 0 0; padding: 0; display: grid; gap: 3px; font-size: 12px; color: var(--muted); }
#staffEmailsPage .pv2-thread-events li { display: flex; gap: 8px; flex-wrap: wrap; align-items: baseline; }
#staffEmailsPage .pv2-thread-events time { font-family: var(--font-data); font-variant-numeric: tabular-nums; color: var(--text); }
#staffEmailsPage .pv2-thread-events small { color: var(--faint); overflow-wrap: anywhere; }
#staffEmailsPage .pv2-thread-outbound-html { margin-top: 8px; }

#staffEmailsPage .pv2-thread-reply { display: grid; gap: 12px; padding: var(--space-4); border: 1px solid var(--line); border-radius: var(--radius-lg); background: var(--surface); }
[data-theme='dark'] #staffEmailsPage .pv2-thread-reply { background: var(--raised); }
#staffEmailsPage .pv2-thread-reply-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
#staffEmailsPage .pv2-thread-reply-head h3 { margin: 0; font-size: 14px; font-weight: 600; color: var(--text); }
#staffEmailsPage .pv2-thread-reply-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.6fr); gap: 12px; }
#staffEmailsPage .pv2-thread-reply-sign { display: grid; grid-template-columns: auto minmax(0, 1fr) minmax(0, 1fr); gap: 10px; align-items: center; padding: 10px 12px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--subtle); }
#staffEmailsPage .pv2-thread-reply-sign input { height: var(--h-md); }
#staffEmailsPage .pv2-thread-reply-sign.is-off input { opacity: 0.5; }
#staffEmailsPage .pv2-thread-reply .pv2-inbox-reply-body { min-height: 150px; }
#staffEmailsPage .pv2-thread-reply-locked { margin: 0; font-size: 12.5px; color: var(--muted); }

/* --- Envoyés : la file, son suivi, le detail ------------------------------- */
#staffEmailsPage .pv2-sent-tools { display: flex; flex-wrap: wrap; gap: 8px 14px; align-items: center; }
#staffEmailsPage .pv2-sent-tools .pv2-search { min-width: 220px; flex: 1 1 220px; max-width: 360px; }
#staffEmailsPage .pv2-table td.pv2-col-parcours { width: 104px; }
#staffEmailsPage .pv2-table td.pv2-col-parcours .pl-journey { display: inline-flex; }
#staffEmailsPage .pv2-origin-chip { max-width: 180px; overflow: hidden; text-overflow: ellipsis; display: inline-block; vertical-align: middle; line-height: 18px; }
#staffEmailsPage .pv2-sent-trace { display: grid; gap: 6px; }
#staffEmailsPage .pv2-sent-trace > div { display: grid; grid-template-columns: 84px minmax(0, 1fr); gap: 10px; align-items: baseline; font-size: 12.5px; color: var(--muted); }
#staffEmailsPage .pv2-sent-trace > div > span:first-child { font-weight: 500; color: var(--faint); }
#staffEmailsPage .pv2-sent-trace > div.is-done > span:first-child,
#staffEmailsPage .pv2-sent-trace > div.is-done { color: var(--text); }
