#staffEmailsPage .pv2-sent-trace time { font-family: var(--font-data); font-variant-numeric: tabular-nums; }
#staffEmailsPage .pv2-sent-actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* --- Séquences : une ligne par sequence, le texte REEL, l'editeur a deux
   colonnes avec l'aperçu vivant ---------------------------------------- */
#staffEmailsPage .mk-auto {
  grid-template-columns: minmax(200px, 260px) minmax(0, 1fr) 40px;
  grid-template-areas: "title effectif switch" "desc effectif switch" "stats actions switch" "editor editor editor";
  align-items: start; column-gap: var(--space-4); row-gap: 4px; padding: 14px var(--space-4);
}
#staffEmailsPage .mk-auto-head strong { grid-area: title; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
#staffEmailsPage .mk-auto-head .mk-switch { grid-area: switch; justify-self: end; align-self: start; }
#staffEmailsPage .mk-auto-desc { grid-area: desc; }
#staffEmailsPage .mk-auto-effectif { grid-area: effectif; display: grid; gap: 3px; min-width: 0; padding-left: 14px; border-left: 1px solid var(--line); }
#staffEmailsPage .mk-auto-effectif-label { font-size: 11px; color: var(--faint); }
#staffEmailsPage .mk-auto-subject { font-size: 13px; font-weight: 500; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#staffEmailsPage .mk-auto-line { font-size: 12.5px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#staffEmailsPage .mk-auto:not(.is-on) .mk-auto-subject { color: var(--muted); }
#staffEmailsPage .mk-auto-stats { grid-area: stats; align-self: end; }
#staffEmailsPage .mk-auto-actions { grid-area: actions; display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; align-self: end; }
#staffEmailsPage .mk-auto-edit { grid-area: editor; display: grid; grid-template-columns: minmax(0, 1fr) minmax(320px, 0.9fr); gap: var(--space-4); max-width: none; margin-top: 12px; }
#staffEmailsPage .mk-auto.is-editing .mk-auto-edit { max-width: none; }
/* Les champs s alignent en haut : sans align-content, la grille s etirait sur la
   hauteur de l apercu voisin et l objet, une seule ligne, gonflait a 108 px. */
#staffEmailsPage .mk-auto-edit-fields { display: grid; gap: 10px; min-width: 0; align-content: start; }
#staffEmailsPage .mk-auto-edit-field .pv2-tokedit.is-single { min-height: var(--h-md); }
#staffEmailsPage .mk-auto-edit-field .pv2-tokedit:not(.is-single) { min-height: 200px; }
/* Cinq boutons sur une ligne mesurent 570 px : sans retour a la ligne, la
   rangee imposait sa largeur a l editeur entier et la page debordait a 390 px. */
#staffEmailsPage .mk-auto-edit-actions { grid-column: 1 / -1; flex-wrap: wrap; justify-content: flex-start; min-width: 0; }
#staffEmailsPage .pv2-seq-preview { display: grid; gap: 8px; min-width: 0; align-content: start; }
/* Apercu du mail en clair ou en sombre (2026-09-17). */
#staffEmailsPage .pv2-theme-choix { display: inline-flex; gap: 2px; padding: 2px; border: 1px solid var(--line); border-radius: var(--radius-sm); }
#staffEmailsPage .pv2-theme-btn { border: 0; background: transparent; font: inherit; font-size: 11.5px; line-height: 1.4; color: var(--muted); padding: 2px 8px; border-radius: 4px; cursor: pointer; }
#staffEmailsPage .pv2-theme-btn.is-active { background: var(--subtle); color: var(--text); }
#staffEmailsPage .pv2-theme-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
#staffEmailsPage .pv2-seq-preview-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; flex-wrap: wrap; font-size: 12px; color: var(--muted); }
#staffEmailsPage .pv2-seq-preview-subject { font-size: 13px; font-weight: 600; color: var(--text); overflow-wrap: anywhere; min-height: 18px; }
#staffEmailsPage .pv2-seq-preview-frame { width: 100%; height: 440px; border: 1px solid var(--line); border-radius: var(--radius-md); background: #ffffff; }
#staffEmailsPage .pv2-seq-groups { display: grid; gap: var(--space-4); }
#staffEmailsPage .pv2-seq-group-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
#staffEmailsPage .pv2-seq-group-head h3 { margin: 0; font-size: 13px; font-weight: 600; color: var(--text); }
#staffEmailsPage .pv2-seq-group-head p { margin: 0; font-size: 12px; color: var(--muted); }
#staffEmailsPage .pv2-seq-editor { margin-top: 0; }
#staffEmailsPage .pv2-seq-editor-cols { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(300px, 0.85fr); gap: var(--space-4); }
#staffEmailsPage .pv2-seq-editor .pv2-composer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
#staffEmailsPage .pv2-seq-pill { border-radius: var(--radius-sm); background: var(--subtle); color: var(--muted); border: 1px solid var(--line); }

/* --- Modèles : une galerie de cartes, un editeur avec aperçu serveur ------- */
#staffEmailsPage .pv2-model-group + .pv2-model-group { margin-top: var(--space-4); }
#staffEmailsPage .pv2-model-group h3 { margin: 0 0 8px; font-size: 12.5px; font-weight: 500; color: var(--muted); }
#staffEmailsPage .pv2-model-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: var(--space-3); }
#staffEmailsPage .pv2-model-card { display: grid; gap: 5px; align-content: start; padding: 12px 14px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); min-width: 0; }
[data-theme='dark'] #staffEmailsPage .pv2-model-card { background: var(--raised); }
#staffEmailsPage .pv2-model-name { display: flex; align-items: center; gap: 8px; min-width: 0; font-size: 13px; font-weight: 600; color: var(--text); }
#staffEmailsPage .pv2-model-name span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#staffEmailsPage .pv2-model-cat { font-size: 11px; color: var(--faint); }
#staffEmailsPage .pv2-model-subject { font-size: 12.5px; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#staffEmailsPage .pv2-model-excerpt { font-size: 12px; line-height: 1.45; color: var(--muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
#staffEmailsPage .pv2-model-actions { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }

/* --- Apparence & signature : le formulaire a gauche, le vrai mail a droite - */
#staffEmailsPage .pv2-design-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(360px, 0.95fr); gap: var(--space-4); align-items: start; }
#staffEmailsPage .pv2-design-form { display: grid; gap: var(--space-3); min-width: 0; }
#staffEmailsPage .pv2-design-block { display: grid; gap: 10px; padding: 14px 16px; border: 1px solid var(--line); border-radius: var(--radius-lg); background: var(--surface); min-width: 0; }
[data-theme='dark'] #staffEmailsPage .pv2-design-block { background: var(--raised); }
#staffEmailsPage .pv2-design-block > h3 { margin: 0; font-size: 13px; font-weight: 600; color: var(--text); }
#staffEmailsPage .pv2-design-hint { margin: -4px 0 0; font-size: 12px; line-height: 1.45; color: var(--muted); }
#staffEmailsPage .pv2-design-presets { display: grid; grid-template-columns: repeat(auto-fit, minmax(118px, 1fr)); gap: 8px; }
#staffEmailsPage .pv2-design-preset { display: grid; gap: 8px; padding: 10px; border: 1px solid var(--line-strong); border-radius: var(--radius-md); background: var(--surface); color: var(--text); font: inherit; text-align: left; cursor: pointer; transition: border-color var(--dur-fast) var(--ease-out-strong); }
#staffEmailsPage .pv2-design-preset.is-active { border-color: var(--text); box-shadow: inset 0 0 0 1px var(--text); }
#staffEmailsPage .pv2-design-preset:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
#staffEmailsPage .pv2-design-preset strong { font-size: 12.5px; font-weight: 600; }
#staffEmailsPage .pv2-design-preset small { font-size: 11.5px; line-height: 1.4; color: var(--muted); }
/* Mini-schemas des gabarits : un papier, une carte, une barre, un bandeau.
   Dessines en tokens, ils disent la STRUCTURE, pas la couleur du centre. */
#staffEmailsPage .pv2-design-schema { position: relative; height: 54px; border-radius: 4px; border: 1px solid var(--line); background: var(--subtle); overflow: hidden; }
#staffEmailsPage .pv2-design-schema::before,
#staffEmailsPage .pv2-design-schema::after { content: ''; position: absolute; left: 10px; right: 10px; }
#staffEmailsPage .pv2-design-schema.is-classique::before { top: 9px; bottom: 6px; border: 1px solid var(--line-strong); border-radius: 4px; background: var(--surface); }
#staffEmailsPage .pv2-design-schema.is-classique::after { top: 17px; height: 3px; left: 18px; right: 30px; border-radius: 2px; background: var(--text); }
#staffEmailsPage .pv2-design-schema.is-epure { background: var(--surface); }
/* Mail simple : deux lignes de texte a gauche, puis la signature (un filet). */
#staffEmailsPage .pv2-design-schema.is-simple { background: var(--surface); }
#staffEmailsPage .pv2-design-schema.is-simple::before { top: 12px; height: 12px; right: 34px; border-top: 2px solid var(--muted); border-bottom: 2px solid var(--muted); }
#staffEmailsPage .pv2-design-schema.is-simple::after { top: 32px; height: 12px; right: auto; width: 38px; border-left: 2px solid var(--line-strong); background: var(--subtle); }
#staffEmailsPage .pv2-design-schema.is-epure::before { top: 14px; height: 3px; right: 26px; border-radius: 2px; background: var(--text); }
#staffEmailsPage .pv2-design-schema.is-epure::after { top: 23px; height: 1px; background: var(--line-strong); }
#staffEmailsPage .pv2-design-schema.is-carte::before { top: 9px; bottom: 6px; border: 1px solid var(--line-strong); border-top: 3px solid var(--text); border-radius: 4px; background: var(--surface); }
#staffEmailsPage .pv2-design-schema.is-carte::after { top: 20px; height: 3px; left: 18px; right: 30px; border-radius: 2px; background: var(--muted); }
#staffEmailsPage .pv2-design-schema.is-contraste::before { top: 0; left: 0; right: 0; height: 18px; background: var(--text); }
#staffEmailsPage .pv2-design-schema.is-contraste::after { top: 24px; bottom: 6px; border: 1px solid var(--line-strong); border-radius: 4px; background: var(--surface); }
#staffEmailsPage .pv2-design-radios { display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: center; }
#staffEmailsPage .pv2-design-swatch { width: 14px; height: 14px; border-radius: var(--radius-sm); border: 1px solid var(--line-strong); display: inline-block; vertical-align: middle; }
#staffEmailsPage .pv2-design-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
#staffEmailsPage .pv2-design-fields .pv2-composer-wide { grid-column: 1 / -1; }
#staffEmailsPage .pv2-design-fields input[type='color'] { width: 44px; height: var(--h-md); padding: 2px; }
#staffEmailsPage .pv2-design-inline { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
#staffEmailsPage .pv2-design-inline input[type='text'],
#staffEmailsPage .pv2-design-inline input[type='url'] { flex: 1 1 200px; min-width: 0; }
#staffEmailsPage .pv2-design-inline input[type='number'] { width: 90px; }
#staffEmailsPage .pv2-design-scope { display: grid; gap: 6px; }
#staffEmailsPage .pv2-design-scope-row { display: grid; grid-template-columns: minmax(0, 1fr) 40px; gap: 4px 12px; align-items: center; padding: 8px 0; border-top: 1px solid var(--line); }
#staffEmailsPage .pv2-design-scope-row:first-child { border-top: 0; }
#staffEmailsPage .pv2-design-scope-row strong { font-size: 13px; font-weight: 500; color: var(--text); }
#staffEmailsPage .pv2-design-scope-row small { grid-column: 1; font-size: 12px; color: var(--muted); }
#staffEmailsPage .pv2-design-scope-row .mk-switch { grid-column: 2; grid-row: 1 / span 2; }
#staffEmailsPage .pv2-design-preview { display: grid; gap: 10px; min-width: 0; position: sticky; top: 12px; }
#staffEmailsPage .pv2-design-preview-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
#staffEmailsPage .pv2-design-preview-subject { font-size: 13px; font-weight: 600; color: var(--text); overflow-wrap: anywhere; min-height: 18px; }
#staffEmailsPage .pv2-design-frame { width: 100%; height: 620px; border: 1px solid var(--line); border-radius: var(--radius-md); background: #ffffff; }
#staffEmailsPage .pv2-design-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
#staffEmailsPage .pv2-design-error { margin: 0; font-size: 12.5px; color: var(--danger); }
#staffEmailsPage .pv2-design-fields input:disabled,
#staffEmailsPage .pv2-design-fields select:disabled,
#staffEmailsPage .pv2-design-fields textarea:disabled { opacity: 0.55; }

/* --- Expéditeurs, L'agent, Exclusions : listes existantes en pleine page --- */
#staffEmailsPage .pv2-settings-seg { display: none; }
#staffEmailsPage .pv2-reply-address { display: grid; gap: 6px; }
#staffEmailsPage .pv2-reply-address strong { font-family: var(--font-data); font-size: 13px; font-weight: 500; color: var(--text); overflow-wrap: anywhere; }
#staffEmailsPage .pv2-agent-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(300px, 0.9fr); gap: var(--space-4); align-items: start; }
#staffEmailsPage .pv2-savoir { margin: 0; }

/* --- Responsive : 1280 / 1100 / 768 / 640, sans debordement horizontal ----- */
@media (max-width: 1280px) {
  #staffEmailsPage .pv2-design-layout { grid-template-columns: minmax(0, 1fr) minmax(320px, 0.9fr); }
}
@media (max-width: 1100px) {
  #staffEmailsPage .pv2-thread-split,
  #staffEmailsPage .pv2-overview-grid,
  #staffEmailsPage .pv2-design-layout,
  #staffEmailsPage .pv2-seq-editor-cols,
  #staffEmailsPage .pv2-agent-grid,
  #staffEmailsPage .mk-auto-edit { grid-template-columns: 1fr; }
  #staffEmailsPage .pv2-design-preview { position: static; }
  #staffEmailsPage .pv2-thread-list { max-height: 420px; }
}
@media (max-width: 900px) {
  #staffEmailsPage .mk-auto { grid-template-columns: minmax(0, 1fr) 40px; grid-template-areas: "title switch" "desc desc" "effectif effectif" "stats stats" "actions actions" "editor editor"; }
  #staffEmailsPage .mk-auto-effectif { padding-left: 0; border-left: 0; }
  #staffEmailsPage .mk-auto-actions { justify-content: flex-start; }
}
@media (max-width: 768px) {
  #staffEmailsPage .pv2-thread-reply-grid,
  #staffEmailsPage .pv2-design-fields,
  #staffEmailsPage .pv2-seq-editor .pv2-composer-grid { grid-template-columns: 1fr; }
  #staffEmailsPage .pv2-thread-reply-sign { grid-template-columns: 1fr; }
  #staffEmailsPage .pv2-design-frame { height: 520px; }
}
@media (max-width: 640px) {
  #staffEmailsPage .pv2-thread-row { padding: 10px 12px; }
  #staffEmailsPage .pv2-thread-detail { padding: 12px; }
  #staffEmailsPage .pl-timeline-msg { padding: 12px; }
  /* Les outils de la file (recherche, export, envoi) passent sous le titre :
     sur une ligne ils sortaient du cadre a droite. */
  #staffEmailsPage .pv2-mail-list .pv2-list-head { flex-wrap: wrap; }
  #staffEmailsPage .pv2-sent-tools { flex: 1 1 100%; }
  #staffEmailsPage .pv2-sent-tools .pv2-search { flex: 1 1 100%; min-width: 0; }
  /* Les tables des exclusions et des campagnes gardent leurs colonnes : elles
     defilent dans leur panneau au lieu de le crever. */
  #staffEmailsPage .pv2-panel-body:has(> .pv2-table) { overflow-x: auto; }
  /* A 390 px, la file garde le message, le statut et la date : l'origine et
     le mini-parcours se lisent dans le detail. */
  #staffEmailsPage .pv2-mail-list .pv2-table th:nth-child(4),
  #staffEmailsPage .pv2-mail-list .pv2-table td:nth-child(4) { display: none; }
  #staffEmailsPage .pv2-sent-tools .pv2-search { max-width: none; }
  #staffEmailsPage .pv2-sent-trace > div { grid-template-columns: 72px minmax(0, 1fr); }
  #staffEmailsPage .pv2-seq-preview-frame { height: 360px; }
  #staffEmailsPage .pv2-design-frame { height: 440px; }
  #staffEmailsPage .pv2-design-presets { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* ============================================================================
   22. COCKPIT FONDATEUR (#staffCockpitPage, permission platform.admin)
   ----------------------------------------------------------------------------
   Meme discipline que la page Emails : composants pv2 reutilises, monochrome
   sauf le sens, filets 1px, aucun jeton nouveau. Seules les classes propres a
   cette page vivent ici, toutes prefixees fck- et scopees.

   ---- KIT DE COMPOSANTS FONDATEUR (langage visuel partage) ------------------
   Toutes les pages proprietaire (Cockpit, Agents, Incidents, Clients, Centres,
   editeurs) montent dans #staffCockpitPage et partagent EXACTEMENT ces briques.
   Un nouveau lot fondateur reutilise ce vocabulaire, il n'en invente pas :
     - En-tete de page ..... .pv2-bar (crumb + h1 20px + .pv2-bar-sub + actions
                             a droite dans .pv2-bar-actions)
     - Bandeau donnees test  .fck-testdata (filet ambre, calme, jamais criard)
     - Carte / section ..... .pv2-panel + .pv2-panel-head>h2 (15/600) +
                             .pv2-panel-sub (12 muted) ; sous-carte : .fck-center-card
     - Sous-titre de bloc .. .fck-sub (12/600 muted)
     - Ligne de KPI ........ .fck-stats > .fck-stat (label .fck-stat-cap muted
                             au-dessus, nombre .fck-stat-num en Geist Mono
                             tabular-nums, indice .fck-stat-hint faint) ;
                             variante d'en-tete business : .fck-biz-stats
     - Liste cle/valeur .... .fck-kv (dt muted / dd mono tabular-nums)
     - Badge statut ........ .pv2-chip[.green|.amber|.red|.blue] (pill, fond
                             -soft + texte couleur, jamais l'info par la couleur
                             seule : le libelle porte le sens)
     - Etat sain ........... .fck-allgood (confirmation calme, vert soft + point)
     - Tableau / liste ..... .pv2-table + .fck-table (header 12 muted, lignes
                             separees par --line, colonnes num a droite en mono)
     - Boutons ............. .pv2-btn (primaire = fond .primary ; secondaire =
                             filet ; discret = .ghost)
   ========================================================================== */
#staffCockpitPage .fck-shell { display: flex; flex-direction: column; gap: 14px; }

/* Bandeau verite : les donnees sont des tests. Ambre = attente/attention,
   filet 1px, pas d'aplat criard : il doit se lire sans hurler. */
#staffCockpitPage .fck-testdata {
  border: 1px solid var(--warning);
  border-left-width: 3px;
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  padding: 10px 14px;
  font-size: 13px;
}

#staffCockpitPage .fck-sub {
  margin: 14px 0 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  text-transform: none;
}

#staffCockpitPage .fck-line { margin: 8px 0; font-size: 13.5px; }
#staffCockpitPage .fck-chips { display: flex; flex-wrap: wrap; gap: 6px; }

/* Page Apprentissage de l'IA : les criteres de la grille, en ligne sous le nom
   de la plateforme. Sans mise en forme ils se collaient les uns aux autres
   (« Verite centre 2Garde-fou 1.8Impact humain 1.4 » : illisible). Le poids est
   en mono, et un critere VENU DU TERRAIN se distingue par son fond accentue -
   jamais par la couleur seule, il porte aussi une bordure. */
#staffCockpitPage .fck-crit {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  margin: 3px 6px 0 0;
  padding: 2px 8px;
  border: 1px solid var(--line);
  border-radius: var(--radius-full);
  font-size: 11.5px;
  color: var(--muted);
  white-space: nowrap;
}
#staffCockpitPage .fck-crit em { font-family: var(--font-data); font-style: normal; color: var(--faint); }
#staffCockpitPage .fck-crit.is-learned { border-color: color-mix(in srgb, var(--accent) 45%, var(--line)); background: var(--accent-soft); color: var(--accent-strong); }
#staffCockpitPage .fck-crit.is-learned em { color: var(--accent-strong); }
#staffCockpitPage .fck-chart-host { margin: 4px 0 2px; }

/* Etat sain de la sante ("Ce qui casse" quand rien ne casse) : confirmation
   calme, pas un simple texte gris. Vert soft + point : le sens est porte par le
   libelle ET le point (jamais la couleur seule). */
#staffCockpitPage .fck-allgood {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 2px 0;
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--success-soft);
  color: var(--success);
  font-size: 13px;
}

#staffCockpitPage .fck-table td { vertical-align: top; padding: 8px 10px 8px 0; }
#staffCockpitPage .fck-row-action { text-align: right; white-space: nowrap; }
#staffCockpitPage .fck-num { font-variant-numeric: tabular-nums; }

/* Cartes centre (adoption) : la grille respire, chaque carte est un filet. */
#staffCockpitPage .fck-center-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 10px;
}
#staffCockpitPage .fck-center-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: var(--surface);
}
#staffCockpitPage .fck-center-card .fck-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}
#staffCockpitPage .fck-kv { margin: 0; display: flex; flex-direction: column; gap: 6px; }
#staffCockpitPage .fck-kv div { display: flex; justify-content: space-between; gap: 10px; }
#staffCockpitPage .fck-kv dt { color: var(--muted); font-size: 12.5px; }
#staffCockpitPage .fck-kv dd { margin: 0; font-size: 12.5px; font-variant-numeric: tabular-nums; }

/* Ligne de KPI fondateur : label muted au-dessus, grand nombre en Geist Mono
   tabular-nums en dessous (DESIGN.md sect.4 : toute donnee passe en mono).
   Base partagee par les stats agents et cout ; la variante .fck-biz-stats en
   fait la grille d'en-tete business du cockpit. */
#staffCockpitPage .fck-stats { display: flex; gap: 22px; flex-wrap: wrap; margin: 6px 0 4px; }
#staffCockpitPage .fck-stat { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
#staffCockpitPage .fck-stat-num {
  font-family: var(--font-data);
  font-size: 24px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  line-height: 1.15;
  color: var(--text);
}
#staffCockpitPage .fck-stat-cap { font-size: 12px; color: var(--muted); line-height: 1.5; }
#staffCockpitPage .fck-stat-hint { font-size: 11px; color: var(--faint); font-variant-numeric: tabular-nums; line-height: 1.4; }

#staffCockpitPage .fck-audit-bar { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 10px; }
#staffCockpitPage .fck-audit-bar .pv2-input { max-width: 220px; }

/* Table des sequences : la premiere colonne est le libelle, les suivantes un
   interrupteur par centre. En-tetes en gris moyen, discipline pv2. */
#staffCockpitPage .fck-seq-table th {
  font-size: 12px;
  font-weight: 500;
  color: var(--muted);
  text-align: left;
  padding: 6px 10px 6px 0;
}

@media (max-width: 640px) {
  #staffCockpitPage .fck-center-grid { grid-template-columns: 1fr; }
  #staffCockpitPage .fck-audit-bar .pv2-input { max-width: none; flex: 1; }
  #staffCockpitPage .fck-seq-table { display: block; overflow-x: auto; }
}

/* --- 22.b Pages dediees de la categorie Plateforme (Agents IA, Incidents,
   Clients). Meme discipline que le cockpit : filets 1px, monochrome sauf
   sens, chiffres tabulaires. Les cartes reutilisent .fck-center-card. --- */
#staffCockpitPage .fck-client-grid { grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); }
/* Graphes fondateur (moteur PinlaneCharts) : le viewBox du moteur fait 560 de
   large ; dans un panneau fondateur pleine largeur (~960px) le SVG serait scale
   ~1.7x et son texte d'axes / labels de mois grossirait d'autant (bug "texte
   enorme"). On BORNE la largeur de rendu a 600px (aligne a gauche) : le SVG
   reste proche de son echelle native, donc les graduations et labels gardent
   une taille normale et lisible. Le board Direction n'est pas concerne : ses
   hotes (.adm-trend-chart, widgets .pab-) vivent deja dans des cartes etroites
   ou l'echelle est bonne, et ce style est scope #staffCockpitPage .fck-chart. */
#staffCockpitPage .fck-chart { min-height: 160px; margin: 4px 0 10px; max-width: 600px; }
#staffCockpitPage .fck-cost-note { margin: 8px 0 0; font-size: 12.5px; }
#staffCockpitPage .fck-incident-list { display: flex; flex-direction: column; gap: 10px; }
#staffCockpitPage .fck-incident {
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  padding: 12px 14px;
}
#staffCockpitPage .fck-incident-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
#staffCockpitPage .fck-incident-msg {
  font-size: 13.5px;
  font-weight: 600;
  min-width: 0;
  overflow-wrap: anywhere;
}
#staffCockpitPage .fck-stack { margin-top: 8px; }
#staffCockpitPage .fck-stack summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 12.5px;
  user-select: none;
}
#staffCockpitPage .fck-stack pre {
  margin: 8px 0 0;
  padding: 10px 12px;
  font-family: var(--font-data);
  font-size: 12px;
  line-height: 1.5;
  background: var(--subtle);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  overflow: auto;
  max-height: 260px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
@media (max-width: 640px) {
  #staffCockpitPage .fck-client-grid { grid-template-columns: 1fr; }
}

/* --- 23. Tendances Direction + lecture visuelle Donnees (adm-trend-*) ------
   Graphiques animes de la categorie Direction : monochrome, sens uniquement
   sur les chips (vert hausse, rouge baisse), bordures 1px, rayons 6-8px,
   chiffres tabulaires, themes clair/sombre via variables. Le moteur de rendu
   vit dans assets/pinlane-charts.js (classes plc-, styles dedies). */
.adm-trend-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
}
.adm-trend-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
  padding: 14px 16px;
  min-width: 0;
}
.adm-trend-wide { grid-column: 1 / -1; }
.adm-trend-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}
.adm-trend-head h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}
.adm-trend-sub {
  margin-top: 2px;
  font-size: 12px;
  color: var(--faint);
}
.adm-trend-chart {
  margin-top: 10px;
  min-height: 40px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.adm-trend-chip {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 2px 8px;
  color: var(--muted);
  background: var(--subtle);
}
.adm-trend-chip.up,
.adm-trend-chip.new {
  color: var(--success);
  border-color: color-mix(in srgb, var(--success) 35%, var(--line));
  background: color-mix(in srgb, var(--success) 10%, var(--surface));
}
.adm-trend-chip.down {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 35%, var(--line));
  background: color-mix(in srgb, var(--danger) 10%, var(--surface));
}
.adm-trend-chip.flat { color: var(--muted); }
.adm-trend-note {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--muted);
}
/* Hote de graphique pas encore monte : hauteur calme reservee, pas de saut
   de layout au dessin. */
.adm-trend-chart:empty,
#staffCockpitPage .fck-chart:empty {
  min-height: 120px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
}
@media (max-width: 700px) {
  .adm-trend-grid { grid-template-columns: 1fr; }
}

/* ============================================================================
   24. DIRECTION : poste d'observation analytics (namespace dir-)
   ----------------------------------------------------------------------------
   Refonte totale de la categorie Direction : une seule page, analytics-first,
   facon Vercel Analytics / Linear Insights. Rupture visuelle nette avec les
   anciens admin-panel/admin-kpi (supprimes du rendu). Aere, calme, la
   hierarchie vient de la taille et de la graisse, la couleur ne dit que le
   sens (vert = hausse/reussi, rouge = baisse, le reste monochrome). Le moteur
   window.PinlaneCharts (classes plc-) dessine, window.PinlaneDateRange (pdr-)
   choisit la fenetre. ======================================================= */
.dir-root {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
/* Entree : la page monte une fois, discretement, translateY + opacity. */
.dir-enter-init { opacity: 0; transform: translateY(8px); }
.dir-enter-active {
  opacity: 1;
  transform: translateY(0);
  transition: opacity 320ms cubic-bezier(0.23, 1, 0.32, 1), transform 320ms cubic-bezier(0.23, 1, 0.32, 1);
}
@media (prefers-reduced-motion: reduce) {
  .dir-enter-init { opacity: 1; transform: none; }
  .dir-enter-active { transition: none; }
}

/* --- Barre de controle : la plage de dates a gauche, la fenetre active a
   droite, toujours lisible meme si le composant tombe. --- */
.dir-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-bottom: 4px;
}
.dir-range-mount { min-width: 0; }
.dir-window {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  text-align: right;
}
.dir-window-range { font-size: 13px; font-weight: 600; color: var(--text); font-variant-numeric: tabular-nums; }
.dir-window-meta { font-size: 12px; color: var(--faint); }
.dir-range-fallback { font-size: 13px; color: var(--muted); }

/* Barre de controle Direction. Le bouton « Journal des modifications » vivait
   ici ; il est parti dans la categorie Plateforme le 2026-07-28 (outil Pinlane,
   pas tableau de bord du gerant), son style part avec lui. */
.dir-controls-right { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }

.dir-note {
  padding: 40px 20px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
  border: 1px dashed var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
}
.dir-note-loading { color: var(--faint); }

/* --- Rangee de KPI : tuiles cliquables, chacune pilote le grand graphique.
   Grand chiffre en Geist Mono, delta en chip, sparkline en pied. --- */
/* 6 tuiles : 2, 3 ou 6 colonnes - jamais 4 ni 5, qui laissaient une tuile
   orpheline seule sur sa rangee (auto-fit choisissait 5 en 1440 px). */
.dir-kpis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
@media (min-width: 760px) { .dir-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (min-width: 1320px) { .dir-kpis { grid-template-columns: repeat(6, minmax(0, 1fr)); } }

/* Etat vide du grand graphe : une phrase calme au lieu d'une ligne plate. */
.dir-focus-empty {
  display: grid;
  gap: 4px;
  align-content: center;
  justify-items: center;
  min-height: 170px;
  padding: var(--space-5);
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-md);
  text-align: center;
}
.dir-focus-empty strong { font-size: 14px; font-weight: 600; color: var(--text); }
.dir-focus-empty span { font-size: 12.5px; color: var(--muted); max-width: 46ch; }
.dir-kpi {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px 16px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  text-align: left;
  cursor: pointer;
  font-family: inherit;
  transition: border-color 160ms ease-out, transform 160ms cubic-bezier(0.23, 1, 0.32, 1), box-shadow 160ms ease-out;
}
@media (hover: hover) {
  .dir-kpi:hover { border-color: var(--line-strong); }
}
.dir-kpi:active { transform: scale(0.99); }
/* Tuile active = celle qui alimente le grand graphique : anneau discret, pas
   de couleur de marque, juste un filet renforce et un fond a peine teinte. */
.dir-kpi.is-active {
  border-color: var(--text);
  box-shadow: inset 0 0 0 1px var(--text);
}
.dir-kpi-label { font-size: 12.5px; color: var(--muted); font-weight: 500; }
.dir-kpi-value {
  font-family: var(--font-data);
  font-size: 26px;
  font-weight: 600;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  line-height: 1.1;
}
.dir-kpi-delta { min-height: 20px; }
.dir-kpi-spark { display: block; height: 40px; margin-top: 2px; }
.dir-kpi-spark:empty { min-height: 40px; }

/* --- Chips de delta : le sens porte la couleur, jamais la decoration. --- */
.dir-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  border-radius: 999px;
  padding: 2px 8px;
  white-space: nowrap;
  border: 1px solid var(--line);
  color: var(--muted);
  background: var(--subtle);
}
.dir-chip-up {
  color: var(--success);
  border-color: color-mix(in srgb, var(--success) 32%, var(--line));
  background: color-mix(in srgb, var(--success) 10%, var(--surface));
}
.dir-chip-down {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 32%, var(--line));
  background: color-mix(in srgb, var(--danger) 10%, var(--surface));
}
.dir-chip-flat, .dir-chip-mute { color: var(--muted); }

/* --- Grand graphique focus : la metrique choisie, pleine largeur. --- */
.dir-focus {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  padding: 18px 20px 20px;
}
.dir-focus-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 10px; }
.dir-focus-title { margin: 0; font-size: 15px; font-weight: 600; color: var(--text); }
.dir-focus-sub { margin: 0; font-size: 12.5px; color: var(--faint); font-variant-numeric: tabular-nums; }
.dir-focus-chart { min-height: 300px; }

/* --- Grille de graphiques secondaires. --- */
.dir-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
.dir-card {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  padding: 16px 18px 18px;
  min-width: 0;
}
.dir-card-wide { grid-column: 1 / -1; }
.dir-card-title { margin: 0 0 12px; font-size: 13.5px; font-weight: 600; color: var(--text); }
.dir-chart { min-height: 180px; }
.dir-chart:empty { min-height: 180px; }

/* --- Tables (voir : top formules, top clients). --- */
.dir-tables {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 14px;
}
.dir-table-card {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  padding: 16px 18px 8px;
  min-width: 0;
}
.dir-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.dir-table th {
  text-align: left;
  font-weight: 500;
  color: var(--faint);
  font-size: 12px;
  padding: 6px 10px 8px 0;
  border-bottom: 1px solid var(--line);
}
.dir-table td { padding: 9px 10px 9px 0; border-bottom: 1px solid var(--line); color: var(--text); vertical-align: top; }
/* La derniere ligne perd son filet du bas - y COMPRIS sur la cellule d en-tete
   de ligne (th scope=row). Sans le th, l underline s arretait au bord du nom et
   dessinait un demi-cadre sous la premiere colonne : lu comme un bug. */
.dir-table tbody tr:last-child td,
.dir-table tbody tr:last-child th { border-bottom: 0; }
.dir-num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.dir-table th.dir-num { text-align: right; }
.dir-client-name { display: block; font-weight: 500; }
.dir-client-contact { display: block; font-size: 11.5px; color: var(--faint); font-variant-numeric: tabular-nums; }

@media (max-width: 860px) {
  .dir-grid { grid-template-columns: 1fr; }
  .dir-controls { flex-direction: column; align-items: stretch; }
  .dir-window { align-items: flex-start; text-align: left; }
}

/* ===========================================================================
   25. PANNEAU FONDATEUR : gestion Centres (fca-) + Equipe/acces (fte-)
   Surfaces de GESTION no-code (creer/configurer/suspendre un centre ;
   membres/roles/permissions/codes). Meme langage visuel que le cockpit
   (pv2-*/fck-*), plus les modales et formulaires de gestion. ============= */
/* ============================================================================
   FRONT-CENTRES : panneau plateforme de gestion no-code des centres.
   ----------------------------------------------------------------------------
   Rendu dans #staffCockpitPage (meme hote que founder-cockpit.js). Discipline
   Vercel/Linear identique : monochrome, le SENS seul porte la couleur (vert =
   actif, ambre = en preparation, rouge = ferme), filets 1px var(--line),
   rayons var(--radius-*), chiffres tabulaires var(--font-data), etats vides
   calmes. On reutilise pv2-*/fck-* quand ca colle (grille de cartes, chips,
   boutons, interrupteurs) ; les classes fca-* n'ajoutent que le manquant :
   resume de config, controle de statut inline, et la MODALE de configuration.
   Motion (Emil Kowalski) : transform/opacity, ease-out, JAMAIS ease-in ni
   scale(0). Etat final immediat sous prefers-reduced-motion.
   AUCUNE balise <header> cote JS : la regle body.staff-mode header l'ecraserait.
   ========================================================================== */

/* --- Resume de config sur la carte ---------------------------------------- */
#staffCockpitPage .fca-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin: 2px 0 4px;
  font-size: 12.5px;
  color: var(--muted);
}
#staffCockpitPage .fca-summary span { display: inline-flex; align-items: center; gap: 5px; }
#staffCockpitPage .fca-summary .fca-sep { color: var(--faint); margin: 0; }
#staffCockpitPage .fca-summary strong { color: var(--text); font-weight: 600; font-variant-numeric: tabular-nums; }

/* Compteurs de la carte : membres / resas 30j / CA 30j. */
#staffCockpitPage .fca-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 4px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}
#staffCockpitPage .fca-metric { display: flex; flex-direction: column; gap: 1px; }
#staffCockpitPage .fca-metric-num {
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -0.01em;
}
#staffCockpitPage .fca-metric-cap { font-size: 11px; color: var(--faint); }

/* Pied de carte Centres (statut editable + Configurer) : reutilise le pied
   partage .fck-card-foot + le select .fck-status-* (voir section 22.c). L'ancien
   segmente 3 etats (.fca-status-seg / .fca-seg-*) est SUPPRIME : dans les cartes
   etroites "en preparation" et "ferme" se chevauchaient (bug corrige). Un select
   tient a toute largeur et rend Centres coherente avec Clients Pinlane. */

/* --- Modale de configuration ---------------------------------------------- */
/* Overlay opacite + panneau translateY(8px)->0. L'animation d'entree ne joue
   qu'a la PREMIERE apparition (classe is-in posee par le JS), jamais sur un
   re-rendu partiel du corps. */
#staffCockpitPage .fca-overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 6vh 16px 24px;
  overflow-y: auto;
  background: var(--backdrop);
}
#staffCockpitPage .fca-overlay.is-in { animation: fca-overlay-in var(--dur-enter, 240ms) var(--ease-out-strong, cubic-bezier(0.23, 1, 0.32, 1)); }
#staffCockpitPage .fca-panel {
  width: min(640px, 100%);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-overlay);
  display: flex;
  flex-direction: column;
  max-height: 88vh;
}
