body:is(.staff-mode, .admin-mode) .dossier-status.is-cancelled { background: var(--danger-soft); color: var(--danger); }
body:is(.staff-mode, .admin-mode) .dossier-facts { display: flex; align-items: start; flex-wrap: wrap; gap: 12px 24px; margin-top: 18px; }
body:is(.staff-mode, .admin-mode) .dossier-fact { display: grid; gap: 3px; min-width: 0; }
body:is(.staff-mode, .admin-mode) .dossier-fact :is(span, small) { font-size: 12px; line-height: 1.4; color: var(--muted); }
body:is(.staff-mode, .admin-mode) .dossier-fact strong { font-size: 14px; line-height: 1.4; font-weight: 600; color: var(--text); overflow-wrap: anywhere; }
body:is(.staff-mode, .admin-mode) .edit-modal-head .close-btn { width: 44px; height: 44px; border-radius: 8px; background: transparent; border: 1px solid var(--control-border); color: var(--muted); }
body:is(.staff-mode, .admin-mode) .edit-modal-head .close-btn:hover { background: var(--subtle); color: var(--text); }
body:is(.staff-mode, .admin-mode) :is(.edit-modal-head .modal-tabs, .dossier-tabs) { padding: 0; gap: 24px; background: transparent; border-radius: 0; }
body:is(.staff-mode, .admin-mode) :is(.edit-modal-head .modal-tabs, .dossier-tabs) .tab { position: relative; flex: 0 1 auto; min-height: 44px; padding: 0 0 14px; border-radius: 0; background: transparent; box-shadow: none; font-size: 13px; color: var(--muted); }
body:is(.staff-mode, .admin-mode) :is(.edit-modal-head .modal-tabs, .dossier-tabs) .tab.active { color: var(--text); font-weight: 650; }
body:is(.staff-mode, .admin-mode) :is(.edit-modal-head .modal-tabs, .dossier-tabs) .tab.active::after { content: ''; position: absolute; bottom: -1px; inset-inline: 0; height: 2px; background: var(--text); }

body:is(.staff-mode, .admin-mode) :is(.es2 .es-grid, .dossier-edit-grid) { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.08fr); gap: 24px; align-items: start; }
body:is(.staff-mode, .admin-mode) :is(.es2 .es-card, .dossier-section) { padding: 0; background: transparent; border: 0; border-radius: 0; gap: 14px; min-width: 0; }
body:is(.staff-mode, .admin-mode) .es2 .es-wide { padding-top: 22px; border-top: 1px solid var(--line); }
body:is(.staff-mode, .admin-mode) :is(.es2 .es-head, .dossier-section-heading) { display: flex; align-items: center; gap: 8px; margin-bottom: 2px; }
body:is(.staff-mode, .admin-mode) :is(.es2 .es-head h4, .dossier-section-heading h4) { font-size: 14px; line-height: 1.4; font-weight: 650; letter-spacing: -.01em; }
body:is(.staff-mode, .admin-mode) .es2 .es-ico { width: 20px; height: 20px; background: transparent; color: var(--muted); border-radius: 0; }
