body:is(.staff-mode, .admin-mode) .es2 .es-contenu { grid-template-columns: minmax(0, 1.3fr) minmax(0, .85fr); gap: 24px; }
body:is(.staff-mode, .admin-mode) .es2 .dossier-program { grid-column: 1 / -1; }
body:is(.staff-mode, .admin-mode) .dossier-edit-lock { border: 0; padding: 0; margin: 0; min-width: 0; }
