body:is(.staff-mode, .admin-mode) .dossier-laser-unit-actions .input { width: 84px; min-width: 0; text-align: center; font-variant-numeric: tabular-nums; }
body:is(.staff-mode, .admin-mode) .dossier-laser-unit-actions .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
