  body:is(.staff-mode, .admin-mode) .dossier-laser-unit { align-items: flex-start; flex-direction: column; gap: 10px; }
  body:is(.staff-mode, .admin-mode) .dossier-laser-unit-actions { width: 100%; }
}
body:is(.staff-mode, .admin-mode) .dossier-activity-body { display: grid; gap: 12px; min-width: 0; }
