/* Compteur unique : les deux gestes restent proches du chiffre qu'ils changent. */
body:is(.staff-mode, .admin-mode) :is(.staff-stepper, .es2 .es-stepper) { display: inline-grid; grid-template-columns: 44px minmax(48px, 1fr) 44px; align-items: stretch; height: 46px; border: 1px solid var(--control-border); border-radius: 8px; overflow: hidden; background: var(--console-input); flex-shrink: 0; }
body:is(.staff-mode, .admin-mode) .es2 .es-stepper { display: grid; }
body:is(.staff-mode, .admin-mode) :is(.staff-stepper-btn, .es2 .es-step) { display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--text); cursor: pointer; }
body:is(.staff-mode, .admin-mode) :is(.staff-stepper-btn, .es2 .es-step):hover:not(:disabled) { background: var(--subtle); }
body:is(.staff-mode, .admin-mode) :is(.staff-stepper-btn, .es2 .es-step):disabled { color: var(--faint); opacity: .45; background: var(--raised); }
body:is(.staff-mode, .admin-mode) .staff-stepper-btn svg { width: 16px; height: 16px; stroke-width: 1.7; }
body:is(.staff-mode, .admin-mode) :is(.staff-stepper-value, .es2 .es-stepper .input) { display: flex; align-items: center; justify-content: center; min-width: 0; min-height: 44px; margin: 0; padding: 0 6px; border: 0; border-inline: 1px solid var(--line); border-radius: 0; background: transparent; font-size: 14px; line-height: 1.4; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text); }
body:is(.staff-mode, .admin-mode) .staff-stepper-value small { font-size: 12px; font-weight: 400; color: var(--muted); margin-left: 3px; }
body:is(.staff-mode, .admin-mode) .staff-stepper:focus-within { outline: 2px solid var(--console-focus); outline-offset: 3px; }
body:is(.staff-mode, .admin-mode) .staff-stepper :focus-visible { outline-offset: -3px; }

body:is(.staff-mode, .admin-mode) :is(.qb-visit-grid, .dossier-options) { gap: 10px; }
body:is(.staff-mode, .admin-mode) .dossier-activities { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; }
body:is(.staff-mode, .admin-mode) :is(.qb-visit-row, .dossier-activity) { background: var(--raised); border: 1px solid var(--line-strong); border-radius: 12px; padding: 14px; gap: 12px; }
body:is(.staff-mode, .admin-mode) :is(.qb-visit-row.is-on, .dossier-activity.selected) { border-color: var(--control-border); background: var(--console-selected-surface); }
body:is(.staff-mode, .admin-mode) :is(.qb-visit-toggle, .dossier-activity-head) { min-height: 28px; font-size: 14px; font-weight: 600; }
body:is(.staff-mode, .admin-mode) .qb-visit-check { width: 18px; height: 18px; border: 1px solid var(--control-border); border-radius: 4px; }
body:is(.staff-mode, .admin-mode) .qb-visit-row.is-on .qb-visit-check { background: var(--console-selected); border-color: var(--console-selected); }
body:is(.staff-mode, .admin-mode) .qb-visit-row.is-on .qb-visit-check::after { border-color: var(--console-selected-text); }
body:is(.staff-mode, .admin-mode) :is(.qb-visit-compteur, .dossier-activity-count) { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; }
body:is(.staff-mode, .admin-mode) :is(.qb-opt-legend, .staff-option-label) { font-size: 12px; font-weight: 500; color: var(--muted); }
body:is(.staff-mode, .admin-mode) .staff-arcade-options { display: grid; gap: 10px; min-width: 0; }
body:is(.staff-mode, .admin-mode) .staff-option-group { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; min-width: 0; }
body:is(.staff-mode, .admin-mode) .staff-option-label { flex-basis: 100%; }
body:is(.staff-mode, .admin-mode) :is(.staff-option-list, .dossier-options) { display: flex; flex-wrap: wrap; gap: 6px; }
body:is(.staff-mode, .admin-mode) :is(.qb-opt, .dossier-option) { min-height: 44px; border: 1px solid var(--control-border); border-radius: 8px; background: var(--surface); color: var(--text); padding: 8px 10px; font-size: 12px; line-height: 1.35; font-weight: 500; }
body:is(.staff-mode, .admin-mode) :is(.qb-opt, .dossier-option):hover:not(:disabled) { background: var(--subtle); }
body:is(.staff-mode, .admin-mode) :is(.qb-opt.is-on, .qb-opt.selected, .dossier-option.selected, .dossier-option.active) { background: var(--console-selected); border-color: var(--console-selected); color: var(--console-selected-text); }
body:is(.staff-mode, .admin-mode) :is(.qb-opt, .dossier-option) small { display: block; color: inherit; font-size: 12px; font-weight: 400; opacity: .85; margin-top: 2px; }
