body:is(.staff-mode, .admin-mode) :is(.dir-card, .dir-table-card, .dir-kpi, .fck-center-card, .fte-role-card)::after { content: none; }
body:is(.staff-mode, .admin-mode) :is(.dir-card, .dir-table-card, .dir-kpi, .fck-center-card, .fte-role-card):hover { transform: none; box-shadow: none; }
body:is(.staff-mode, .admin-mode) #staffCockpitPage .pv2-btn.primary:hover { box-shadow: none; }

/* Finitions du lot relu : les statuts et notes restent nommes, sans bandes
   decoratives ni deuxieme cadre a l'interieur de la fiche. */
