/* La sortie du plein ecran garde son accent, mais avec le jeton du bouton
   principal : blanc sur #74b6ff ne faisait que 2,1:1 en sombre. */
body:is(.staff-mode, .admin-mode) :is(.table-box, .planning-box).expanded:not(.hidden) :is(#tableToggle, #planningToggle, #laserPlanningToggle) {
  background: var(--console-selected);
  border-color: var(--console-selected);
  color: var(--console-selected-text);
}
@media (max-width: 600px) {
  /* Le compteur en haut a droite de l onglet, a cote du nom : en bas a gauche
     il flottait comme un bouton orphelin. */
  body.staff-mode .staff-resource-tab:not(.hidden) { flex-direction: row; align-items: flex-start; }
  body.staff-mode .staff-resource-tab > span:first-child { min-width: 0; flex: 1 1 auto; }
