@media (max-width: 768px) {
  /* « Agrandir » et la recherche sur la meme ligne : seul sur sa ligne, le
     bouton ajoutait 56 px avant la premiere carte. */
  #staffTableBox:not(.expanded) .table-head .table-actions { flex-wrap: nowrap; }
  #staffTableBox:not(.expanded) .table-head .table-actions .search-wrap { flex: 1 1 auto; width: auto; min-width: 0; }
}

/* LA VALIDATION PAR L EQUIPE, dans la modale d une formule (2026-10-05) :
   trois choix exclusifs cote a cote, la phrase dessous dit ce qui se passera
   pour le client. */
.pev-valid { display: grid; gap: 8px; margin: 4px 0 6px; }
.pev-valid-label { font-size: 13px; font-weight: 600; color: var(--text); }
.pev-seg { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 4px; padding: 4px; border: 1px solid var(--line-strong); border-radius: 10px; background: var(--subtle); }
.pev-seg-btn { min-height: 40px; padding: 6px 10px; border: 0; border-radius: 7px; background: transparent; color: var(--muted); font: 600 13px/1.2 var(--font-ui); cursor: pointer; text-align: center; }
.pev-seg-btn:hover { color: var(--text); background: color-mix(in srgb, var(--surface) 60%, transparent); }
.pev-seg-btn.is-on { background: var(--surface); color: var(--text); box-shadow: 0 1px 2px rgb(0 0 0 / 0.12), 0 0 0 1px var(--line-strong); }
.pev-seg-btn:focus-visible { outline: 2px solid var(--console-focus, var(--accent)); outline-offset: 2px; }
[data-theme='dark'] .pev-seg-btn.is-on { background: var(--raised); }
@media (max-width: 560px) { .pev-seg { grid-template-columns: minmax(0, 1fr); } }

/* ==========================================================================
   TARIFS & FORMULES, EN LISTE (2026-10-05). Movsar : « la page complete ou ya
   les formules modifiables etc cest super mal foutu ameliore tout [...] du meme
   style que les trucs figma ». Mesure avant : des cartes de hauteurs
   differentes dans une grille, quatre boutons par carte, un bandeau rouge qui
   sortait de sa carte (F6, F7, F8) et la corbeille coupee au bord.
   Chaque rayon devient un panneau, chaque offre une LIGNE : le nom, ce qu elle
   contient, son prix et ses gestes aux memes places d une ligne a l autre.
   Le DOM ne change pas (les gates et les gestes visent les memes attributs) :
   c est la grille qui place les morceaux.
   ========================================================================== */
#staffPricingPage .pv2-catalog-section {
  gap: 0;
  margin-top: 18px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
  overflow: hidden;
}
#staffPricingPage .pv2-section-head {
  gap: 6px 10px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--line);
}
#staffPricingPage .pv2-section-head h3 {
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--text);
}
#staffPricingPage .pv2-section-head h3::before { display: none; }
#staffPricingPage .pv2-section-head > span:not(.pv2-section-legend) {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 7px;
  border-radius: 999px;
  background: var(--subtle);
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}
#staffPricingPage .pv2-section-head > .pv2-btn { margin-left: auto; }
#staffPricingPage .pv2-section-legend { order: 9; font-size: 12.5px; color: var(--muted); }

#staffPricingPage .pv2-catalog { display: block; }
#staffPricingPage .pv2-price-card {
  grid-template-columns: minmax(190px, 1.05fr) minmax(0, 2fr) 116px auto;
  grid-template-areas:
    "nom    contenu prix gestes"
    "etats  tags    prix gestes"
    "chiffres chiffres chiffres chiffres";
  column-gap: 22px;
  row-gap: 6px;
  align-items: start;
  padding: 14px 18px;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}
#staffPricingPage .pv2-catalog > .pv2-price-card:last-child { border-bottom: 0; }
#staffPricingPage .pv2-price-card:hover { background: color-mix(in srgb, var(--subtle) 55%, transparent); border-color: var(--line); }
#staffPricingPage .pv2-price-card.selected { box-shadow: inset 3px 0 0 var(--console-selected, var(--accent)); border-color: var(--line); }
#staffPricingPage .pv2-price-head { display: contents; }
#staffPricingPage .pv2-price-head > div:first-child { grid-area: nom; min-width: 0; }
#staffPricingPage .pv2-price-head strong { font-size: 14.5px; font-weight: 650; overflow-wrap: anywhere; }
#staffPricingPage .pv2-price-head small { font-size: 12px; color: var(--muted); }
#staffPricingPage :is(.pv2-price-amount, .pv2-price-onsite) { grid-area: prix; justify-self: end; text-align: right; }
#staffPricingPage .pv2-price-amount { font-size: 18px; color: var(--text); }
#staffPricingPage .pv2-price-amount small { color: var(--muted); }
#staffPricingPage .pev-badges { grid-area: etats; }
#staffPricingPage .pv2-price-desc { grid-area: contenu; font-size: 13px; color: var(--muted); }
#staffPricingPage .pv2-price-tags { grid-area: tags; }
#staffPricingPage .pv2-price-stats { grid-area: chiffres; margin: 2px 0 0; padding-top: 8px; font-size: 12px; color: var(--muted); }
#staffPricingPage .pev-card-foot {
  grid-area: gestes;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  border: 0;
  justify-self: end;
}
#staffPricingPage .pev-foot-main { flex-wrap: nowrap; }
/* Un avertissement long se replie DANS sa ligne, jamais au-dela. */
#staffPricingPage .pv2-chip { white-space: normal; text-align: left; line-height: 1.3; }
/* Une activite : nom, prix et gestes, sur une ligne. */
#staffPricingPage .pv2-activity-card {
  grid-template-columns: minmax(190px, 1.05fr) minmax(0, 2fr) 116px auto;
  grid-template-areas: "nom etats prix gestes";
  padding: 11px 18px;
  align-items: center;
}
#staffPricingPage .pv2-activity-card :is(.pv2-price-amount, .pv2-price-onsite) { align-self: center; }

@media (max-width: 900px) {
  #staffPricingPage .pv2-price-card,
  #staffPricingPage .pv2-activity-card {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "nom prix"
      "etats etats"
      "contenu contenu"
      "tags tags"
      "chiffres chiffres"
      "gestes gestes";
    padding: 14px 16px;
  }
  #staffPricingPage .pev-card-foot { justify-self: stretch; flex-wrap: wrap; }
  #staffPricingPage .pev-foot-main { flex-wrap: wrap; }
  #staffPricingPage .pev-foot-danger { margin-left: auto; }
  #staffPricingPage .pv2-section-head > .pv2-btn { margin-left: 0; }
}
/* Une etiquette longue qui passe sur deux lignes garde un angle doux : en
   pilule, deux lignes faisaient une forme de gelule. */
#staffPricingPage .pv2-chip { border-radius: 6px; }
@media (max-width: 900px) {
  /* Les gestes sur UNE ligne au telephone : les trois actions se partagent la
     place, la corbeille garde sa case a droite (elle passait seule dessous). */
  #staffPricingPage .pev-card-foot { flex-wrap: nowrap; }
  #staffPricingPage .pev-foot-main { flex: 1 1 auto; display: grid; grid-template-columns: 1.45fr 1fr 1fr; flex-wrap: nowrap; min-width: 0; }
  #staffPricingPage .pev-foot-main:has(> :only-child) { grid-template-columns: auto; justify-content: start; }
  #staffPricingPage .pev-foot-main .pv2-btn { min-width: 0; padding: 0 8px; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  #staffPricingPage .pev-foot-danger { flex: none; margin-left: 0; }
}

/* LA VALIDATION PAR L EQUIPE dans Etablissement (2026-10-05) : le niveau en
   trois choix, sa phrase, puis chaque situation avec son explication et son
   exemple, cochable. */
.estab-validation .estab-seg { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 4px; padding: 4px; border: 1px solid var(--line-strong); border-radius: 10px; background: var(--subtle); margin-top: 4px; }
.estab-validation .estab-seg-btn { min-height: 40px; border: 0; border-radius: 7px; background: transparent; color: var(--muted); font: 600 13px/1.2 var(--font-ui); cursor: pointer; }
.estab-validation .estab-seg-btn:hover { color: var(--text); }
.estab-validation .estab-seg-btn.is-on { background: var(--surface); color: var(--text); box-shadow: 0 1px 2px rgb(0 0 0 / 0.12), 0 0 0 1px var(--line-strong); }
[data-theme='dark'] .estab-validation .estab-seg-btn.is-on { background: var(--raised); }
.estab-validation .estab-seg-btn:focus-visible { outline: 2px solid var(--console-focus, var(--accent)); outline-offset: 2px; }
.estab-valid-dit { margin: 8px 0 4px; font-size: 13px; color: var(--text); }
.estab-situations { list-style: none; margin: 6px 0 0; padding: 0; display: grid; gap: 2px; }
.estab-situation .establishment-toggle { align-items: flex-start; padding: 8px 0; }
.estab-situation .establishment-toggle > span:last-child { display: grid; gap: 2px; }
.estab-situation .estab-sit-titre { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; }
.estab-situation b { font-weight: 600; color: var(--text); }
.estab-situation em { font-style: normal; font-size: 11px; font-weight: 600; line-height: 18px; padding: 0 7px; border-radius: 999px; border: 1px solid var(--line-strong); background: var(--subtle); color: var(--muted); }
.estab-situation small { font-size: 12.5px; line-height: 1.45; color: var(--muted); }
.estab-situation .estab-sit-ex { color: var(--faint); }
.estab-situation:not(.is-on) b { color: var(--muted); }
.estab-situation input:disabled { cursor: default; }
/* Les deux cartes prennent toute la largeur : la liste des situations se lit
   en colonnes au lieu d une tour, et la boite de secours ne s etire plus a la
   hauteur de sa voisine. */
.estab-edit-grid > .estab-validation, .estab-edit-grid > .estab-secours { grid-column: 1 / -1; }
.estab-validation .estab-card-hint, .estab-validation .estab-valid-dit, .estab-secours .estab-card-hint { max-width: 76ch; }
.estab-validation .estab-seg { max-width: 460px; }
.estab-situations { grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); column-gap: 28px; }
.estab-secours .field { max-width: 560px; }

/* LA PAGE SECOURS (2026-10-05) : imprimer en premier, puis l etat reel de la
   boite de secours et de la sauvegarde, puis la marche a suivre. */
.secours-page { display: grid; gap: var(--space-4); }
.secours-page .sec-carte { display: grid; align-content: start; gap: var(--space-3); padding: var(--space-5); border: 1px solid var(--line); border-radius: var(--radius-lg); background: var(--surface); }
.secours-page .sec-carte .sec-tete { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: start; gap: 4px 12px; }
.secours-page .sec-carte .sec-tete h3 { margin: 0; font-size: 15px; font-weight: 650; color: var(--text); }
.secours-page .sec-carte .sec-tete p { grid-column: 1 / -1; margin: 2px 0 0; font-size: 13px; line-height: 1.5; color: var(--muted); max-width: 78ch; }
.secours-page .sec-imprimer-ligne { display: flex; align-items: flex-end; gap: 16px; flex-wrap: wrap; }
.secours-page .sec-date { display: grid; gap: 6px; font-size: 12.5px; font-weight: 600; color: var(--muted); }
.secours-page .sec-date input { min-height: 40px; padding: 0 12px; border: 1px solid var(--control-border, var(--line-strong)); border-radius: 8px; background: var(--page); color: var(--text); font: 500 14px var(--font-ui); }
.secours-page .sec-boutons { display: flex; gap: 8px; flex-wrap: wrap; }
.secours-page .sec-boutons .btn { min-height: 40px; }
.secours-page .sec-boutons .btn.is-busy { opacity: .6; cursor: progress; }
.secours-page .sec-grille { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 380px), 1fr)); gap: var(--space-4); }
.secours-page .sec-etat { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; font-size: 12px; font-weight: 650; line-height: 20px; border: 1px solid transparent; }
.secours-page .sec-etat::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.secours-page .sec-etat.is-ok { color: #13703a; background: #e7f6ec; border-color: #b9e3c7; }
.secours-page .sec-etat.is-off { color: #8a4b00; background: #fff4e0; border-color: #f2d29b; }
[data-theme='dark'] .secours-page .sec-etat.is-ok { color: #7fe0a3; background: rgb(46 160 90 / .14); border-color: rgb(46 160 90 / .35); }
[data-theme='dark'] .secours-page .sec-etat.is-off { color: #ffc46b; background: rgb(240 160 40 / .12); border-color: rgb(240 160 40 / .32); }
.secours-page .sec-adresses { display: flex; gap: 6px; flex-wrap: wrap; }
.secours-page .sec-vide { margin: 0; font-size: 13px; line-height: 1.5; color: var(--muted); }
.secours-page .sec-lignes { display: grid; }
.secours-page .sec-ligne { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding: 10px 0; border-top: 1px solid var(--line); font-size: 13px; color: var(--muted); }
.secours-page .sec-ligne span { display: grid; gap: 2px; }
.secours-page .sec-ligne small { font-size: 11.5px; color: var(--faint); }
.secours-page .sec-ligne b { color: var(--text); font-weight: 600; text-align: right; }
.secours-page .sec-consignes ol { margin: 0; padding: 0; list-style: none; counter-reset: etape; display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 12px; }
.secours-page .sec-consignes li { counter-increment: etape; display: grid; gap: 4px; padding: 14px 14px 14px 52px; position: relative; border: 1px solid var(--line); border-radius: 10px; background: var(--page); }
.secours-page .sec-consignes li::before { content: counter(etape); position: absolute; left: 14px; top: 13px; width: 26px; height: 26px; border-radius: 7px; display: grid; place-items: center; background: var(--text); color: var(--surface); font: 700 13px var(--font-ui); }
.secours-page .sec-consignes li b { font-size: 13.5px; color: var(--text); }
.secours-page .sec-consignes li span { font-size: 12.5px; line-height: 1.5; color: var(--muted); }
.secours-page .sec-erreur { margin: 0; padding: 10px 14px; border-radius: 8px; background: var(--subtle); color: var(--text); font-size: 13px; }
@media (max-width: 640px) {
  .secours-page .sec-boutons, .secours-page .sec-boutons .btn { width: 100%; }
  .secours-page .sec-ligne { flex-direction: column; gap: 2px; }
  .secours-page .sec-ligne b { text-align: left; }
}

/* --- DONNEES CLIENTS (2026-10-05) : activite, fidelite, provenance. --------
   Meme coque que .dir-prov / .dir-ret ; tableaux qui defilent dans leur carte
   au lieu d elargir la page. */
.dir-don {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  padding: 18px 20px 20px;
  margin: 18px 0;
}
.dir-don-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
.dir-don-title { margin: 0; font-size: 15px; font-weight: 600; color: var(--text); }
.dir-don-sub { margin: 2px 0 0; font-size: 12.5px; color: var(--faint); }
.dir-don-export {
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  padding: 7px 14px;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease;
}
.dir-don-export:hover { background: var(--surface-2, rgba(0, 0, 0, 0.04)); }
.dir-don-export.is-busy { opacity: 0.6; cursor: progress; }
.dir-don-body { animation: dir-decision-in 360ms cubic-bezier(0.23, 1, 0.32, 1) both; }
.dir-don-body .dir-card { background: var(--surface); }
.dir-don-note { margin: -6px 0 10px; font-size: 12px; color: var(--faint); }
.dir-don-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
.dir-don-table td, .dir-don-table th { white-space: nowrap; }
.dir-don-table td:first-child { white-space: normal; min-width: 140px; }
.dir-don-tuiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}
.dir-don-tuile {
  border: 1px solid var(--line);
  border-radius: var(--radius-md, 10px);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.dir-don-tuile-mot { font-size: 12px; color: var(--faint); }
.dir-don-tuile-val { font-size: 20px; font-weight: 650; color: var(--text); font-variant-numeric: tabular-nums; }
.dir-don-tuile-aide { font-size: 11.5px; color: var(--faint); }
@media (max-width: 720px) {
  .dir-don { padding: 14px 14px 16px; }
}

/* --- ENCAISSE REEL ET ABSENCE (2026-10-06) : sous les boutons d etat de la
   fiche. Discret quand tout est normal, clair quand le groupe est absent. */
.pos-encaisse { margin-top: 10px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; color: var(--muted, var(--text)); }
.pos-encaisse-ligne strong { color: var(--text); font-variant-numeric: tabular-nums; }
.pos-encaisse-corriger summary { cursor: pointer; font-size: 12.5px; color: var(--faint); width: max-content; }
.pos-encaisse-corriger summary:hover { color: var(--text); }
.pos-encaisse-form { display: grid; grid-template-columns: minmax(110px, 140px) minmax(0, 1fr) auto; gap: 8px; align-items: end; margin-top: 8px; }
.pos-encaisse-form label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--faint); min-width: 0; }
.pos-encaisse-form input { font: inherit; font-size: 13.5px; padding: 8px 10px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); color: var(--text); min-width: 0; }
.pos-absent { margin-top: 10px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 13px; }
.pos-absent.is-on { padding: 10px 12px; border-radius: 12px; background: color-mix(in srgb, var(--danger, #c0392b) 10%, transparent); color: var(--text); }
@media (max-width: 560px) { .pos-encaisse-form { grid-template-columns: 1fr; } }

/* NOTES CLIENT INTERNES (2026-10-05, journal Pinlane 378). Etaient dans
   pinlane-staff-notes.css, une 8e feuille que DESIGN.md §8 interdit ; rangees
   ici, a la meme place dans la cascade (la feuille se chargeait juste apres
   celle-ci). */
.staff-note-scope{border:0;margin:0 0 12px;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.staff-note-scope legend{font-size:12px;font-weight:600;margin-bottom:8px;color:var(--muted)}.staff-note-scope label{display:flex;align-items:flex-start;gap:8px;padding:10px;border:1px solid var(--line);border-radius:8px;cursor:pointer;min-height:44px}.staff-note-scope label:has(input:checked){border-color:var(--accent);background:var(--accent-soft)}.staff-note-scope label:has(input:disabled){opacity:.6;cursor:default}.staff-note-scope input{margin:3px 0 0;accent-color:var(--accent)}.staff-note-scope span{font-size:13px;font-weight:600}.staff-note-scope small{display:block;font-size:12px;font-weight:400;color:var(--muted);line-height:1.45;margin-top:3px}.staff-note-scope-caption{font-size:12px;color:var(--muted);line-height:1.5;margin:6px 0 10px}.staff-note-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.staff-note-actions button,.staff-client-note-head button,.staff-note-load-error button{min-height:44px;padding:8px 12px}.staff-client-note{padding:12px 0;margin-bottom:12px;border-bottom:1px solid var(--line)}.staff-client-note-head{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.staff-client-note-head>b{font-size:13px}.staff-client-note-head>span{font-size:12px;color:var(--muted)}.staff-client-note-head>button{margin-left:auto}.staff-client-note>p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0;line-height:1.55}.staff-client-note-editor{margin-bottom:16px}.staff-client-note-editor>label{display:block;font-size:13px;font-weight:600;margin-bottom:8px}.staff-note-error{font-size:13px;color:var(--warning);line-height:1.5;margin:8px 0}.staff-note-load-error{display:flex;align-items:center;gap:8px;justify-content:space-between;font-size:12px;color:var(--muted)}.gc-note-equipe .staff-note-actions{flex-shrink:0}.staff-note-scope input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:420px){.staff-note-scope{grid-template-columns:1fr}.staff-client-note-head>button{margin-left:0}}

/* LE PLANNING LASER TIENT SUR UN TELEPHONE (2026-10-07).
   A 390 px, le plein ecran gardait ses deux colonnes de comptoir : la file
   « Parties a placer » (340 px) prenait l ecran et la grille des heures etait
   repoussee hors de l ecran, a droite (50 px visibles). Hors plein ecran,
   l agenda gardait 900 px de large et sa colonne Capacite ne se voyait qu en
   faisant defiler de cote. Sous 600 px : la file passe AU-DESSUS, en bandeau
   qu on fait defiler de cote, et la grille prend toute la largeur dessous ; les
   trois colonnes de l agenda se partagent la largeur de l ecran. Le glisser au
   doigt reste le meme : appui long sur une partie, puis la tranche voulue (la
   timeline defile seule au bord de l ecran). Tablette et ordinateur : rien ne
   change. */
@media (max-width: 600px) {
  .laser-agenda { min-width: 0; }
  .laser-agenda-header,
  .laser-agenda-row,
  .planning-box.expanded .laser-agenda-header,
  .planning-box.expanded .laser-agenda-row { grid-template-columns: 58px minmax(0, 1fr) 64px; }
  .laser-agenda-header > div { padding: 8px; }
  .laser-agenda-time,
  .laser-agenda-capacity { padding: 8px; }
  .laser-session-slot { margin: 6px; }
  .laser-session-stack { padding: 6px; }
  .laser-agenda-row.is-empty .laser-session-slot.is-empty { padding: 0 10px; }

  .laser-planning-box.expanded .planning-grid-wrap {
    display: flex;
    flex-direction: column;
  }
  .laser-planning-box.expanded .laser-pass-queue {
    flex: 0 0 auto;
    height: auto;
    max-height: 34vh;
    border-right: 0;
    border-bottom: 1px solid var(--line);
    padding: 10px 12px;
    gap: 8px;
  }
  .laser-planning-box.expanded .laser-pass-list {
    flex-direction: row;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    padding-bottom: 2px;
  }
  .laser-planning-box.expanded .laser-pass-list > * { flex: 0 0 auto; max-width: 78vw; }
  .laser-planning-box.expanded .laser-pass-card { width: auto; min-width: 168px; }
  .laser-planning-box.expanded .laser-agenda { flex: 1 1 auto; }
}

/* --- TOUTES LES RESERVATIONS, RESSERREE (2026-10-08) ---------------------
   Movsar : « les cartes juste un peu plus petites », « plus simple, plus
   visible ». Le dessin ne change pas : memes blocs, memes couleurs. Part ce
   qui prenait de la place sans rien dire de plus :
   - la boite de la liste plafonnee a 704 px : sur une tablette debout, un
     tiers de l ecran restait noir sous la derniere carte. Elle descend
     jusqu au bas de l ecran (--liste-haut, pose par ajusterHauteurListe) ;
   - un encadre sur deux lignes, son titre seul sur la premiere : le titre
     passe devant son texte ;
   - au telephone, l aide d une activite (« Dans 20 min ») seule sur une
     troisieme ligne : elle remonte a droite du nom ;
   - les marges des bandeaux, des sections et des cartes ;
   - trois tailles de nom selon l ecran (17, 16 et 15 px) : une seule. */
.table-box#staffTableBox:not(.hidden):not(.expanded) { max-height: max(480px, calc(100dvh - var(--liste-haut, 280px) - 12px)); }
#staffTableBox .gc-sections { gap: 14px; padding: 10px 12px 16px; }
#staffTableBox .gc-section > .res-section-head.gc-band { margin-bottom: 8px; padding: 6px 12px; }
#staffTableBox .gc-band-icon { width: 24px; height: 24px; }
#staffTableBox .res-row.gc { padding: 10px 12px; gap: 8px; }
#staffTableBox .res-row.gc.is-done { padding: 8px 12px; gap: 0; }
#staffTableBox .gc-grid { gap: 8px; }
#staffTableBox .gc-who h4.res-row-name { font-size: 16px; }
#staffTableBox .gc-flags { gap: 4px; }
#staffTableBox .gc-flag { flex-direction: row; flex-wrap: wrap; align-items: baseline; gap: 0 8px; padding: 5px 10px; line-height: 1.4; }
#staffTableBox .gc-flag b { flex: none; }
#staffTableBox .gc-flag.tone-note span { font-size: 13px; }
/* Plein ecran : les cartes s alignent sur les puces et l en-tete. */
#staffTableBox.expanded:not(.hidden) .gc-sections { padding-inline: clamp(18px, 2.6vw, 46px); }
#staffTableBox.expanded:not(.hidden) .gc-sections .res-section-head { padding-inline: 12px; }
/* Les puces de la tablette debout tiennent sur une ligne qui defile, comme
   au telephone : repliees sur deux lignes, le filet de « Avec note »
   tombait seul en tete de la seconde. */
@media (min-width: 769px) and (max-width: 1180px) {
  #staffTableBox .status-filters { flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  #staffTableBox .status-filters::-webkit-scrollbar { display: none; }
  #staffTableBox .status-group { flex-wrap: nowrap; }
  #staffTableBox .status-chip { flex: none; }
}
/* Sur une ligne qui defile, un groupe de puces ne retrecit pas : il glissait
   sous « Avec note » et coupait « Payées » en deux. */
@media (max-width: 1180px) {
  #staffTableBox .status-group { flex: none; }
}
@media (max-width: 560px) {
  #staffTableBox .gc-sections { padding: 10px 8px 14px; }
  #staffTableBox .res-row.gc { padding: 10px; }
  #staffTableBox .gc-step-state { grid-column: 3; grid-row: 1; justify-self: end; align-self: start; }
  #staffTableBox .gc-step.is-cochable .gc-step-state { grid-column: 4; grid-row: 1; }
  #staffTableBox .gc-step-price { grid-row: 2; }
}
/* « En retard » se voit avant d etre choisie ; les nouvelles puces ont la
   couleur de leur bandeau (Payées comme les terminees, Pas venus neutre). */
.status-chip.is-late:not(.active) { color: var(--danger); border-color: color-mix(in srgb, var(--danger) 45%, var(--line-strong)); }
.status-chip.active.late { background: var(--danger-soft); border-color: var(--danger); color: var(--danger); }
.status-chip.active.paid { background: var(--success-soft); border-color: var(--success); color: var(--success); }
.status-chip.active.absent { background: var(--subtle); border-color: var(--line-strong); color: var(--text); }
/* La fiche et la Vue d ensemble disent le mot de la liste, dans sa couleur. */
body:is(.staff-mode, .admin-mode) .dossier-status.is-pending { background: var(--accent-soft); color: var(--accent-strong); }
body:is(.staff-mode, .admin-mode) .dossier-status.is-late { background: var(--danger-soft); color: var(--danger); }
body:is(.staff-mode, .admin-mode) .dossier-status.is-arrived { background: var(--success-soft); color: var(--success); }
body:is(.staff-mode, .admin-mode) .dossier-status.is-closing { background: var(--warning-soft); color: var(--warning); }
body:is(.staff-mode, .admin-mode) .dossier-status.is-absent { background: var(--subtle); color: var(--muted); }
.dashboard-detail-row.late { border-left: 2px solid var(--danger); }
.dashboard-detail-row.arrived { border-left-color: var(--success); }
.dashboard-detail-row.closing { border-left: 2px solid var(--warning); }
.dashboard-detail-row.absent { border-left: 2px solid var(--line-strong); }
/* Le signal de synchronisation de la liste : absent quand tout va bien. */
.liste-sync { display: inline-flex; align-items: center; gap: 6px; margin-left: 4px; padding: 3px 10px; border-radius: 999px; background: var(--warning-soft); color: var(--warning); font-size: 12.5px; font-weight: 600; white-space: nowrap; }
.liste-sync::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.liste-sync.is-stale { background: var(--danger-soft); color: var(--danger); }
.liste-sync[hidden] { display: none; }
